import React, { useState, useRef, useEffect } from 'react';

// Types
import type { User, VehicleType, UserRole } from '../types';

// Utils
import { stripFirestore } from '../utils';

// Services
import { auth, db } from '../services/firebase';
import { 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword 
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { doc, getDoc, setDoc } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Icons
import { 
  Bike, Mail, Lock, User as UserIcon, 
  Smartphone, ShieldCheck, Eye, EyeOff,
  ChevronLeft, Car, Globe, Trophy, 
  Loader2, ArrowRight, MessageCircle, Zap, MapPin, Building
} from 'lucide-react';

const APP_LOGO_ICON = "https://img.icons8.com/fluency-systems-filled/512/FFFFFF/bicycle.png";

const Onboarding: React.FC<{ onComplete: () => void }> = ({ onComplete }) => {
  const [step, setStep] = useState(0);
  const slides = [
    { title: "أهلاً بك في المنوفية", body: "وصـــلــهــا هو تطبيق التوصيل الأول والوحيد المخصص لخدمة كافة مراكز وقرى محافظة المنوفية.", icon: <Globe className="h-16 w-16 md:h-20 md:w-20 text-emerald-400" />, color: "from-[#2D9469] to-[#1e6346]" },
    { title: "كباتن ثقة وأمان", body: "كل رحلاتك مراقبة ومؤمنة، كباتننا هم جيرانك وأهلك من قلب مراكزنا العشرة.", icon: <ShieldCheck className="h-16 w-16 md:h-20 md:w-20 text-emerald-400" />, color: "from-slate-900 to-slate-800" },
    { title: "وفر وقتك وفلوسك", body: "أفضل تسعيرة في أقاليم مصر، مع نظام نقاط ومكافآت لكل مشوار بتمشي معانا فيه.", icon: <Trophy className="h-16 w-16 md:h-20 md:w-20 text-amber-400" />, color: "from-indigo-900 to-indigo-800" }
  ];

  return (
    <div className={`fixed inset-0 z-[5000] flex flex-col transition-all duration-1000 bg-gradient-to-br ${slides[step].color}`}>
       <div className="flex-1 flex flex-col items-center justify-center p-6 md:p-10 text-center text-white space-y-8 md:space-y-12">
          <div className="bg-white/10 p-10 md:p-16 rounded-[3rem] md:rounded-[4.5rem] backdrop-blur-3xl animate-in zoom-in duration-700 shadow-2xl border border-white/20">
             {slides[step].icon}
          </div>
          <div className="space-y-4 md:space-y-6 animate-in slide-in-from-bottom duration-1000 max-w-sm">
             <h2 className="text-3xl md:text-5xl font-black tracking-tighter leading-tight">{slides[step].title}</h2>
             <p className="text-white/70 font-bold leading-relaxed text-sm md:text-md">{slides[step].body}</p>
          </div>
       </div>
       <div className="p-8 md:p-12 pb-16 md:pb-20 space-y-8 md:space-y-12 bg-gradient-to-t from-black/20 to-transparent">
          <div className="flex justify-center gap-2 md:gap-3">
             {slides.map((_, i) => (
               <div key={i} className={`h-2 rounded-full transition-all duration-500 ${i === step ? 'w-12 md:w-16 bg-white' : 'w-2 bg-white/20'}`}></div>
             ))}
          </div>
          <div className="flex gap-3 md:gap-4">
             {step > 0 && (
               <button onClick={() => setStep(step - 1)} className="p-5 md:p-7 bg-white/10 text-white rounded-2xl md:rounded-[2.5rem] backdrop-blur-md active:scale-90 transition-all">
                 <ArrowRight className="h-5 w-5 md:h-6 md:w-6" />
               </button>
             )}
             <button onClick={() => step < slides.length - 1 ? setStep(step + 1) : onComplete()} className="flex-1 bg-white text-slate-900 py-5 md:py-7 rounded-[2rem] md:rounded-[3rem] font-black text-lg md:text-xl flex items-center justify-center gap-3 md:gap-4 shadow-xl active:scale-95 transition-all">
                {step === slides.length - 1 ? 'ابدأ الآن' : 'استمر'}
                <ChevronLeft className="h-5 w-5 md:h-6 md:w-6" />
             </button>
          </div>
       </div>
    </div>
  );
};

const Login: React.FC<{ onLogin: (user: User) => void }> = ({ onLogin }) => {
  const [showOnboarding, setShowOnboarding] = useState(true);
  const [isRegistering, setIsRegistering] = useState(false);
  const [step, setStep] = useState<'INPUT' | 'OTP'>('INPUT');
  const [role, setRole] = useState<'CUSTOMER' | 'DRIVER'>('CUSTOMER');
  const [vehicleType, setVehicleType] = useState<VehicleType>('TOKTOK');

  // Sign Up States
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [center, setCenter] = useState('');
  const [village, setVillage] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  // OTP State
  const [otp, setOtp] = useState(['', '', '', '', '', '']);
  const otpRefs = useRef<(HTMLInputElement | null)[]>([]);

  // Login States
  const [loginIdentifier, setLoginIdentifier] = useState(''); // Email or Phone
  const [loginPassword, setLoginPassword] = useState('');
  const [rememberMe, setRememberMe] = useState(false);

  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  const centers = ["شبين الكوم", "منوف", "أشمون", "الباجور", "قويسنا", "بركة السبع", "تلا", "السادات", "الشهداء"];

  const validateSignUp = () => {
    // 1. Name Validation (4 words)
    if (name.trim().split(/\s+/).length < 4) {
      setErrorMsg("برجاء إدخال الاسم رباعي لضمان التوثيق");
      return false;
    }
    // 2. Phone Validation
    const phoneRegex = /^(010|011|012|015)[0-9]{8}$/;
    if (!phoneRegex.test(phone)) {
      setErrorMsg("رقم الهاتف غير صحيح، يجب أن يبدأ بـ 010 أو 011 أو 012 أو 015 ويكون 11 رقم");
      return false;
    }
    // 3. Email Validation
    if (!email.includes('@') || email.length < 5) {
      setErrorMsg("البريد الإلكتروني غير صحيح");
      return false;
    }
    // 4. Password Validation
    const passRegex = /^(?=.*[a-zA-Z])(?=.*[0-9]).{8,}$/;
    if (!passRegex.test(password)) {
      setErrorMsg("كلمة المرور يجب ألا تقل عن 8 أحرف وتحتوي على حرف ورقم");
      return false;
    }
    // 5. Match Passwords
    if (password !== confirmPassword) {
      setErrorMsg("كلمة المرور غير متطابقة");
      return false;
    }
    // 6. Center Validation
    if (!center) {
      setErrorMsg("برجاء اختيار المركز");
      return false;
    }
    // 7. Village Validation
    if (village.length < 3) {
      setErrorMsg("برجاء إدخال اسم القرية أو المنطقة بشكل صحيح");
      return false;
    }
    // 8. Vehicle Validation
    if (role === 'DRIVER' && !vehicleType) {
      setErrorMsg("برجاء اختيار نوع المركبة");
      return false;
    }
    return true;
  };

  const sendWhatsAppCodeRequest = () => {
    const adminWhatsApp = "201065019364";
    const message = `أطلب كود التحقق لرقم: ${phone}`;
    const url = `https://wa.me/${adminWhatsApp}?text=${encodeURIComponent(message)}`;
    window.open(url, '_blank');
  };

  const handleOtpChange = (index: number, value: string) => {
    if (isNaN(Number(value))) return;
    const newOtp = [...otp];
    newOtp[index] = value.substring(value.length - 1);
    setOtp(newOtp);

    if (value && index < 5) {
      otpRefs.current[index + 1]?.focus();
    }
  };

  const handleOtpKeyDown = (index: number, e: React.KeyboardEvent) => {
    if (e.key === 'Backspace' && !otp[index] && index > 0) {
      otpRefs.current[index - 1]?.focus();
    }
  };

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setErrorMsg(null);

    if (isRegistering && step === 'INPUT') {
      if (!validateSignUp()) return;
      setStep('OTP');
      return;
    }

    setLoading(true);
    try {
      if (isRegistering) {
        // Here we simulate OTP verification
        if (otp.join('').length < 6) {
          setErrorMsg("الكود غير مكتمل");
          setLoading(false);
          return;
        }

        const userCredential = await createUserWithEmailAndPassword(auth, email, password);
        const userData: User = {
          id: userCredential.user.uid, 
          email, 
          name, 
          phone, 
          role,
          status: role === 'DRIVER' ? 'PENDING_APPROVAL' : 'APPROVED',
          vehicleType: role === 'DRIVER' ? vehicleType : undefined,
          zoneId: center,
          wallet: { balance: 0, totalEarnings: 0, withdrawn: 0 }
        };
        await setDoc(doc(db, "users", userCredential.user.uid), userData);

        if (role === 'DRIVER') {
           const driverMsg = `أنا الكابتن ${name} اللي تم تسجيله أريد تفعيل حسابي`;
           window.open(`https://wa.me/201065019364?text=${encodeURIComponent(driverMsg)}`, '_blank');
        }

        onLogin(userData);
      } else {
        // Login logic
        const userCredential = await signInWithEmailAndPassword(auth, loginIdentifier.includes('@') ? loginIdentifier : `${loginIdentifier}@waslha.com`, loginPassword);
        const userSnap = await getDoc(doc(db, "users", userCredential.user.uid));
        if (userSnap.exists()) onLogin(stripFirestore(userSnap.data()) as User);
      }
    } catch (err: any) { 
      setErrorMsg("حدث خطأ في البيانات، يرجى التأكد والمحاولة ثانية.");
    } finally { setLoading(false); }
  };

  if (showOnboarding) return <Onboarding onComplete={() => setShowOnboarding(false)} />;

  return (
    <div className="min-h-screen bg-[#f8fafc] flex flex-col items-center justify-center p-4 md:p-6 font-['Cairo'] relative overflow-y-auto">
      <div className="w-full max-w-lg bg-white rounded-[3rem] md:rounded-[4rem] shadow-2xl border border-slate-50 overflow-hidden animate-in zoom-in duration-700 my-8">
        <div className="bg-[#2D9469] p-8 md:p-12 text-center relative">
          <div className="bg-white/10 p-4 rounded-[2rem] backdrop-blur-xl border border-white/20 inline-block mb-4 shadow-2xl">
             <img src={APP_LOGO_ICON} alt="Logo" className="h-12 w-12 md:h-16 md:w-16 mx-auto" />
          </div>
          <h1 className="text-3xl md:text-5xl font-black text-white tracking-tighter">وصـــلــهــا</h1>
          <p className="text-emerald-100/60 font-bold text-[9px] uppercase tracking-[0.4em] mt-2">المنوفية • الأمان والسرعة</p>
        </div>

        <div className="p-6 md:p-10">
          {errorMsg && <div className="mb-6 p-4 bg-rose-50 text-rose-600 rounded-2xl text-xs font-black border border-rose-100 animate-in shake duration-300">{errorMsg}</div>}

          <form onSubmit={handleAuth} className="space-y-4">
            {isRegistering ? (
              step === 'INPUT' ? (
                <div className="space-y-4 animate-in slide-in-from-bottom duration-500">
                  {/* User Role Selection */}
                  <div className="flex bg-slate-100 p-1.5 rounded-[1.5rem]">
                    <button type="button" onClick={() => setRole('CUSTOMER')} className={`flex-1 py-3 rounded-xl font-black text-[11px] transition-all ${role === 'CUSTOMER' ? 'bg-white text-[#2D9469] shadow-md' : 'text-slate-400'}`}>عميل</button>
                    <button type="button" onClick={() => setRole('DRIVER')} className={`flex-1 py-3 rounded-xl font-black text-[11px] transition-all ${role === 'DRIVER' ? 'bg-white text-[#2D9469] shadow-md' : 'text-slate-400'}`}>كابتن</button>
                  </div>

                  {/* Fields */}
                  <div className="relative group">
                    <UserIcon className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 h-5 w-5 group-focus-within:text-[#2D9469] transition-colors" />
                    <input type="text" placeholder="الاسم الرباعي" value={name} onChange={e => setName(e.target.value)} required className="w-full bg-slate-50 rounded-2xl py-4 md:py-5 pr-12 pl-6 font-bold outline-none text-sm border-2 border-transparent focus:border-emerald-500 transition-all" />
                  </div>

                  <div className="relative group">
                    <Smartphone className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 h-5 w-5 group-focus-within:text-[#2D9469] transition-colors" />
                    <input type="tel" placeholder="رقم الهاتف (010...)" value={phone} onChange={e => setPhone(e.target.value)} required className="w-full bg-slate-50 rounded-2xl py-4 md:py-5 pr-12 pl-6 font-bold outline-none text-sm text-left border-2 border-transparent focus:border-emerald-500 transition-all" dir="ltr" />
                  </div>

                  <div className="relative group">
                    <Mail className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 h-5 w-5 group-focus-within:text-[#2D9469] transition-colors" />
                    <input type="email" placeholder="البريد الإلكتروني" value={email} onChange={e => setEmail(e.target.value)} required className="w-full bg-slate-50 rounded-2xl py-4 md:py-5 pr-12 pl-6 font-bold outline-none text-sm text-left border-2 border-transparent focus:border-emerald-500 transition-all" dir="ltr" />
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="relative">
                      <Lock className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 h-5 w-5" />
                      <input type={showPassword ? "text" : "password"} placeholder="كلمة المرور" value={password} onChange={e => setPassword(e.target.value)} required className="w-full bg-slate-50 rounded-2xl py-4 md:py-5 pr-12 pl-12 font-bold outline-none text-sm text-left border-2 border-transparent focus:border-emerald-500 transition-all" dir="ltr" />
                      <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 hover:text-slate-500">{showPassword ? <EyeOff className="h-5 w-5" /> : <Eye className="h-5 w-5" />}</button>
                    </div>
                    <div className="relative">
                      <Lock className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 h-5 w-5" />
                      <input type={showConfirmPassword ? "text" : "password"} placeholder="تأكيد كلمة المرور" value={confirmPassword} onChange={e => setConfirmPassword(e.target.value)} required className="w-full bg-slate-50 rounded-2xl py-4 md:py-5 pr-12 pl-12 font-bold outline-none text-sm text-left border-2 border-transparent focus:border-emerald-500 transition-all" dir="ltr" />
                      <button type="button" onClick={() => setShowConfirmPassword(!showConfirmPassword)} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 hover:text-slate-500">{showConfirmPassword ? <EyeOff className="h-5 w-5" /> : <Eye className="h-5 w-5" />}</button>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="relative opacity-60">
                      <Globe className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-400 h-5 w-5" />
                      <input type="text" value="المنوفية" disabled className="w-full bg-slate-100 rounded-2xl py-4 md:py-5 pr-12 font-black text-sm border-2 border-slate-200 cursor-not-allowed" />
                    </div>
                    <div className="relative">
                      <Building className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 h-5 w-5" />
                      <select value={center} onChange={e => setCenter(e.target.value)} required className="w-full bg-slate-50 rounded-2xl py-4 md:py-5 pr-12 pl-6 font-bold outline-none text-sm appearance-none border-2 border-transparent focus:border-emerald-500 transition-all">
                        <option value="">اختر المركز</option>
                        {centers.map(c => <option key={c} value={c}>{c}</option>)}
                      </select>
                    </div>
                  </div>

                  <div className="relative group">
                    <MapPin className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 h-5 w-5 group-focus-within:text-[#2D9469] transition-colors" />
                    <input type="text" placeholder="اسم القرية / المنطقة" value={village} onChange={e => setVillage(e.target.value)} required className="w-full bg-slate-50 rounded-2xl py-4 md:py-5 pr-12 pl-6 font-bold outline-none text-sm border-2 border-transparent focus:border-emerald-500 transition-all" />
                  </div>

                  {role === 'DRIVER' && (
                    <div className="space-y-2 animate-in slide-in-from-top duration-300">
                       <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4">نوع المركبة المعتمد</label>
                       <div className="relative">
                        <Car className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 h-5 w-5" />
                        <select value={vehicleType} onChange={e => setVehicleType(e.target.value as VehicleType)} className="w-full bg-slate-50 rounded-2xl py-4 md:py-5 pr-12 pl-6 font-bold outline-none text-sm appearance-none border-2 border-transparent focus:border-emerald-500 transition-all">
                          <option value="TOKTOK">توك توك 🛺</option>
                          <option value="MOTORCYCLE">موتوسيكل 🏍️</option>
                          <option value="CAR">سيارة 🚗</option>
                        </select>
                       </div>
                    </div>
                  )}

                  <button type="submit" className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black shadow-xl active:scale-95 transition-all flex items-center justify-center gap-3">متابعة التسجيل</button>
                </div>
              ) : (
                <div className="space-y-8 text-center animate-in zoom-in duration-500">
                  <div className="space-y-2">
                    <h2 className="text-2xl font-black">أثبت هويتك</h2>
                    <p className="text-xs font-bold text-slate-400">أدخل الكود المكون من 6 أرقام</p>
                  </div>

                  <div className="flex justify-center gap-2" dir="ltr">
                    {otp.map((digit, idx) => (
                      <input
                        key={idx}
                        ref={el => otpRefs.current[idx] = el}
                        type="text"
                        maxLength={1}
                        value={digit}
                        onChange={e => handleOtpChange(idx, e.target.value)}
                        onKeyDown={e => handleOtpKeyDown(idx, e)}
                        className="w-10 h-14 md:w-12 md:h-16 bg-slate-50 border-2 border-slate-100 rounded-xl text-center text-2xl font-black focus:border-emerald-500 focus:ring-4 focus:ring-emerald-500/5 outline-none transition-all"
                      />
                    ))}
                  </div>

                  <div className="space-y-4">
                    <button type="button" onClick={sendWhatsAppCodeRequest} className="text-emerald-600 font-black text-xs hover:underline flex items-center justify-center gap-2 mx-auto">
                       <MessageCircle className="h-4 w-4" /> طلب الكود عبر الواتساب
                    </button>
                    <button type="submit" disabled={loading} className="w-full bg-[#2D9469] text-white py-5 rounded-2xl font-black shadow-xl active:scale-95 transition-all flex items-center justify-center gap-3">
                       {loading ? <Loader2 className="h-5 w-5 animate-spin" /> : 'إنشاء الحساب الآن'}
                    </button>
                    <button type="button" onClick={() => setStep('INPUT')} className="text-slate-400 font-bold text-[10px] uppercase tracking-widest">تعديل البيانات</button>
                  </div>
                </div>
              )
            ) : (
              <div className="space-y-5 animate-in slide-in-from-bottom duration-500">
                <div className="relative group">
                  <UserIcon className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 h-5 w-5 group-focus-within:text-[#2D9469] transition-colors" />
                  <input type="text" placeholder="رقم الهاتف أو البريد" value={loginIdentifier} onChange={e => setLoginIdentifier(e.target.value)} required className="w-full bg-slate-50 rounded-2xl py-4 md:py-5 pr-12 pl-6 font-bold outline-none text-sm text-left border-2 border-transparent focus:border-emerald-500 transition-all" dir="ltr" />
                </div>

                <div className="relative group">
                  <Lock className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 h-5 w-5 group-focus-within:text-[#2D9469] transition-colors" />
                  <input type={showPassword ? "text" : "password"} placeholder="كلمة المرور" value={loginPassword} onChange={e => setLoginPassword(e.target.value)} required className="w-full bg-slate-50 rounded-2xl py-4 md:py-5 pr-12 pl-12 font-bold outline-none text-sm text-left border-2 border-transparent focus:border-emerald-500 transition-all" dir="ltr" />
                  <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 hover:text-slate-500">{showPassword ? <EyeOff className="h-5 w-5" /> : <Eye className="h-5 w-5" />}</button>
                </div>

                <div className="flex items-center justify-between px-2">
                  <label className="flex items-center gap-2 cursor-pointer group">
                    <input type="checkbox" checked={rememberMe} onChange={e => setRememberMe(e.target.checked)} className="w-4 h-4 rounded border-slate-300 text-[#2D9469] focus:ring-[#2D9469]" />
                    <span className="text-[11px] font-bold text-slate-400 group-hover:text-slate-600">تذكرني</span>
                  </label>
                  <button type="button" className="text-[11px] font-black text-slate-400 hover:text-[#2D9469]">نسيت كلمة المرور؟</button>
                </div>

                <button type="submit" disabled={loading} className="w-full bg-[#2D9469] text-white py-5 rounded-2xl font-black shadow-xl active:scale-95 transition-all flex items-center justify-center gap-3">
                   {loading ? <Loader2 className="h-5 w-5 animate-spin" /> : 'دخول الآونة'}
                </button>
              </div>
            )}

            <button type="button" onClick={() => { setIsRegistering(!isRegistering); setStep('INPUT'); setErrorMsg(null); }} className="w-full text-slate-400 font-black text-[10px] py-4 uppercase tracking-widest hover:text-[#2D9469] transition-colors">
              {isRegistering ? 'لديك حساب بالفعل؟ سجل دخولك' : 'جديد في المنوفية؟ سجل معنا الآن'}
            </button>
          </form>
        </div>
      </div>
      <footer className="app-footer text-[10px] opacity-60">© جميع الحقوق محفوظة لشركة وصـــلــهــا المنوفية</footer>
    </div>
  );
};

export default Login;

@import url('https://fonts.googleapis.com/css2?family=Cairo:wght@400;500;600;700;900&display=swap');

:root {
  --brand-emerald: #10b981;
  --brand-emerald-deep: #065f46;
  --slate-950: #020617;
  --slate-900: #0f172a;
  --header-height-mobile: 70px;
  --header-height-desktop: 90px;
}

* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  -webkit-tap-highlight-color: transparent;
}

body {
  font-family: 'Cairo', sans-serif;
  direction: rtl;
  background-color: #f1f5f9;
  color: var(--slate-900);
  -webkit-font-smoothing: antialiased;
  overflow-x: hidden;
}

/* Animations */
@keyframes shake {
  0%, 100% { transform: translateX(0); }
  25% { transform: translateX(-5px); }
  75% { transform: translateX(5px); }
}
.shake { animation: shake 0.3s ease-in-out; }

@keyframes slideDown {
  from { opacity: 0; transform: translateY(-10px); }
  to { opacity: 1; transform: translateY(0); }
}
.animate-slide-down { animation: slideDown 0.3s ease-out forwards; }

/* OTP Inputs */
input[type="text"]:focus, 
input[type="tel"]:focus, 
input[type="email"]:focus, 
input[type="password"]:focus, 
select:focus {
  transform: scale(1.01);
  box-shadow: 0 10px 15px -3px rgba(16, 185, 129, 0.1);
}

/* Scrollbar customization */
.no-scrollbar::-webkit-scrollbar { display: none; }
.no-scrollbar { -ms-overflow-style: none; scrollbar-width: none; }

/* Responsive Grid Adjustments */
@media (max-width: 640px) {
  .grid-cols-2 {
    grid-template-columns: 1fr;
  }
}

.app-container {
  display: flex;
  flex-direction: column;
  height: 100vh;
  width: 100vw;
}

.main-content {
  position: relative;
  flex: 1;
  display: flex;
  flex-direction: column;
  overflow: hidden;
}

.rh-layout {
  position: relative;
  height: 100%;
  width: 100%;
  display: flex;
  flex-direction: column;
}

.rh-ui-panel {
  position: fixed;
  bottom: 0;
  left: 0;
  right: 0;
  z-index: 100;
  background: white;
  border-top-left-radius: 2.5rem;
  border-top-right-radius: 2.5rem;
  box-shadow: 0 -15px 50px -12px rgba(0, 0, 0, 0.15);
  max-height: 85vh;
  overflow-y: auto;
  padding-bottom: calc(5rem + env(safe-area-inset-bottom));
  transition: all 0.5s cubic-bezier(0.16, 1, 0.3, 1);
}

@media (min-width: 768px) {
  .rh-ui-panel {
    bottom: 2rem;
    left: 2rem;
    right: auto;
    width: 420px;
    border-radius: 2.5rem;
    max-height: calc(100% - 4rem);
    padding-bottom: 2rem;
  }
}

@media (min-width: 1024px) {
  .rh-layout { flex-direction: row-reverse; }
  .rh-map-view { position: relative; flex: 1; margin: 1.5rem; border-radius: 2.5rem; overflow: hidden; }
  .rh-ui-panel {
    position: relative;
    width: 450px;
    height: calc(100% - 3rem);
    max-height: none;
    margin: 1.5rem 0 1.5rem 1.5rem;
    border-radius: 2.5rem;
    box-shadow: none;
    border: 1px solid #e2e8f0;
    bottom: auto; left: auto; right: auto;
  }
}

.app-footer {
  width: 100%;
  text-align: center;
  padding: 2rem 0;
  color: #94a3b8;
  font-weight: 600;
}

.label-strong { font-weight: 900; color: var(--slate-950); }
.helper-text { font-weight: 600; color: #64748b; font-size: 0.75rem; }

import React, { useState, useRef, useEffect } from 'react';

// Types
import type { User, VehicleType, UserRole } from '../types';

// Utils
import { stripFirestore } from '../utils';

// Services
import { auth, db } from '../services/firebase';
import { 
  signInWithEmailAndPassword, 
  createUserWithEmailAndPassword 
} from "https://www.gstatic.com/firebasejs/10.7.1/firebase-auth.js";
import { doc, getDoc, setDoc } from "https://www.gstatic.com/firebasejs/10.7.1/firebase-firestore.js";

// Icons
import { 
  Bike, Mail, Lock, User as UserIcon, 
  Smartphone, ShieldCheck, Eye, EyeOff,
  ChevronLeft, Car, Globe, Trophy, 
  Loader2, ArrowRight, MessageCircle, Zap, MapPin, Building
} from 'lucide-react';

const APP_LOGO_ICON = "https://img.icons8.com/fluency-systems-filled/512/FFFFFF/bicycle.png";

const Onboarding: React.FC<{ onComplete: () => void }> = ({ onComplete }) => {
  const [step, setStep] = useState(0);
  const slides = [
    { title: "أهلاً بك في المنوفية", body: "وصـــلــهــا هو تطبيق التوصيل الأول والوحيد المخصص لخدمة كافة مراكز وقرى محافظة المنوفية.", icon: <Globe className="h-16 w-16 md:h-20 md:w-20 text-emerald-400" />, color: "from-[#2D9469] to-[#1e6346]" },
    { title: "كباتن ثقة وأمان", body: "كل رحلاتك مراقبة ومؤمنة، كباتننا هم جيرانك وأهلك من قلب مراكزنا العشرة.", icon: <ShieldCheck className="h-16 w-16 md:h-20 md:w-20 text-emerald-400" />, color: "from-slate-900 to-slate-800" },
    { title: "وفر وقتك وفلوسك", body: "أفضل تسعيرة في أقاليم مصر، مع نظام نقاط ومكافآت لكل مشوار بتمشي معانا فيه.", icon: <Trophy className="h-16 w-16 md:h-20 md:w-20 text-amber-400" />, color: "from-indigo-900 to-indigo-800" }
  ];

  return (
    <div className={`fixed inset-0 z-[5000] flex flex-col transition-all duration-1000 bg-gradient-to-br ${slides[step].color}`}>
       <div className="flex-1 flex flex-col items-center justify-center p-6 md:p-10 text-center text-white space-y-8 md:space-y-12">
          <div className="bg-white/10 p-10 md:p-16 rounded-[3rem] md:rounded-[4.5rem] backdrop-blur-3xl animate-in zoom-in duration-700 shadow-2xl border border-white/20">
             {slides[step].icon}
          </div>
          <div className="space-y-4 md:space-y-6 animate-in slide-in-from-bottom duration-1000 max-w-sm">
             <h2 className="text-3xl md:text-5xl font-black tracking-tighter leading-tight">{slides[step].title}</h2>
             <p className="text-white/70 font-bold leading-relaxed text-sm md:text-md">{slides[step].body}</p>
          </div>
       </div>
       <div className="p-8 md:p-12 pb-16 md:pb-20 space-y-8 md:space-y-12 bg-gradient-to-t from-black/20 to-transparent">
          <div className="flex justify-center gap-2 md:gap-3">
             {slides.map((_, i) => (
               <div key={i} className={`h-2 rounded-full transition-all duration-500 ${i === step ? 'w-12 md:w-16 bg-white' : 'w-2 bg-white/20'}`}></div>
             ))}
          </div>
          <div className="flex gap-3 md:gap-4">
             {step > 0 && (
               <button onClick={() => setStep(step - 1)} className="p-5 md:p-7 bg-white/10 text-white rounded-2xl md:rounded-[2.5rem] backdrop-blur-md active:scale-90 transition-all">
                 <ArrowRight className="h-5 w-5 md:h-6 md:w-6" />
               </button>
             )}
             <button onClick={() => step < slides.length - 1 ? setStep(step + 1) : onComplete()} className="flex-1 bg-white text-slate-900 py-5 md:py-7 rounded-[2rem] md:rounded-[3rem] font-black text-lg md:text-xl flex items-center justify-center gap-3 md:gap-4 shadow-xl active:scale-95 transition-all">
                {step === slides.length - 1 ? 'ابدأ الآن' : 'استمر'}
                <ChevronLeft className="h-5 w-5 md:h-6 md:w-6" />
             </button>
          </div>
       </div>
    </div>
  );
};

const Login: React.FC<{ onLogin: (user: User) => void }> = ({ onLogin }) => {
  const [showOnboarding, setShowOnboarding] = useState(true);
  const [isRegistering, setIsRegistering] = useState(false);
  const [step, setStep] = useState<'INPUT' | 'OTP'>('INPUT');
  const [role, setRole] = useState<'CUSTOMER' | 'DRIVER'>('CUSTOMER');
  const [vehicleType, setVehicleType] = useState<VehicleType>('TOKTOK');

  // Sign Up States
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [center, setCenter] = useState('');
  const [village, setVillage] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  // OTP State
  const [otp, setOtp] = useState(['', '', '', '', '', '']);
  const otpRefs = useRef<(HTMLInputElement | null)[]>([]);

  // Login States
  const [loginIdentifier, setLoginIdentifier] = useState(''); // Email or Phone
  const [loginPassword, setLoginPassword] = useState('');
  const [rememberMe, setRememberMe] = useState(false);

  const [loading, setLoading] = useState(false);
  const [errorMsg, setErrorMsg] = useState<string | null>(null);

  const centers = ["شبين الكوم", "منوف", "أشمون", "الباجور", "قويسنا", "بركة السبع", "تلا", "السادات", "الشهداء"];

  const validateSignUp = () => {
    // 1. Name Validation (4 words)
    if (name.trim().split(/\s+/).length < 4) {
      setErrorMsg("برجاء إدخال الاسم رباعي لضمان التوثيق");
      return false;
    }
    // 2. Phone Validation
    const phoneRegex = /^(010|011|012|015)[0-9]{8}$/;
    if (!phoneRegex.test(phone)) {
      setErrorMsg("رقم الهاتف غير صحيح، يجب أن يبدأ بـ 010 أو 011 أو 012 أو 015 ويكون 11 رقم");
      return false;
    }
    // 3. Email Validation
    if (!email.includes('@') || email.length < 5) {
      setErrorMsg("البريد الإلكتروني غير صحيح");
      return false;
    }
    // 4. Password Validation
    const passRegex = /^(?=.*[a-zA-Z])(?=.*[0-9]).{8,}$/;
    if (!passRegex.test(password)) {
      setErrorMsg("كلمة المرور يجب ألا تقل عن 8 أحرف وتحتوي على حرف ورقم");
      return false;
    }
    // 5. Match Passwords
    if (password !== confirmPassword) {
      setErrorMsg("كلمة المرور غير متطابقة");
      return false;
    }
    // 6. Center Validation
    if (!center) {
      setErrorMsg("برجاء اختيار المركز");
      return false;
    }
    // 7. Village Validation
    if (village.length < 3) {
      setErrorMsg("برجاء إدخال اسم القرية أو المنطقة بشكل صحيح");
      return false;
    }
    // 8. Vehicle Validation
    if (role === 'DRIVER' && !vehicleType) {
      setErrorMsg("برجاء اختيار نوع المركبة");
      return false;
    }
    return true;
  };

  const sendWhatsAppCodeRequest = () => {
    const adminWhatsApp = "201065019364";
    const message = `أطلب كود التحقق لرقم: ${phone}`;
    const url = `https://wa.me/${adminWhatsApp}?text=${encodeURIComponent(message)}`;
    window.open(url, '_blank');
  };

  const handleOtpChange = (index: number, value: string) => {
    if (isNaN(Number(value))) return;
    const newOtp = [...otp];
    newOtp[index] = value.substring(value.length - 1);
    setOtp(newOtp);

    if (value && index < 5) {
      otpRefs.current[index + 1]?.focus();
    }
  };

  const handleOtpKeyDown = (index: number, e: React.KeyboardEvent) => {
    if (e.key === 'Backspace' && !otp[index] && index > 0) {
      otpRefs.current[index - 1]?.focus();
    }
  };

  const handleAuth = async (e: React.FormEvent) => {
    e.preventDefault();
    setErrorMsg(null);

    if (isRegistering && step === 'INPUT') {
      if (!validateSignUp()) return;
      setStep('OTP');
      return;
    }

    setLoading(true);
    try {
      if (isRegistering) {
        // Here we simulate OTP verification
        if (otp.join('').length < 6) {
          setErrorMsg("الكود غير مكتمل");
          setLoading(false);
          return;
        }

        const userCredential = await createUserWithEmailAndPassword(auth, email, password);
        const userData: User = {
          id: userCredential.user.uid, 
          email, 
          name, 
          phone, 
          role,
          status: role === 'DRIVER' ? 'PENDING_APPROVAL' : 'APPROVED',
          vehicleType: role === 'DRIVER' ? vehicleType : undefined,
          zoneId: center,
          wallet: { balance: 0, totalEarnings: 0, withdrawn: 0 }
        };
        await setDoc(doc(db, "users", userCredential.user.uid), userData);

        if (role === 'DRIVER') {
           const driverMsg = `أنا الكابتن ${name} اللي تم تسجيله أريد تفعيل حسابي`;
           window.open(`https://wa.me/201065019364?text=${encodeURIComponent(driverMsg)}`, '_blank');
        }

        onLogin(userData);
      } else {
        // Login logic
        const userCredential = await signInWithEmailAndPassword(auth, loginIdentifier.includes('@') ? loginIdentifier : `${loginIdentifier}@waslha.com`, loginPassword);
        const userSnap = await getDoc(doc(db, "users", userCredential.user.uid));
        if (userSnap.exists()) onLogin(stripFirestore(userSnap.data()) as User);
      }
    } catch (err: any) { 
      setErrorMsg("حدث خطأ في البيانات، يرجى التأكد والمحاولة ثانية.");
    } finally { setLoading(false); }
  };

  if (showOnboarding) return <Onboarding onComplete={() => setShowOnboarding(false)} />;

  return (
    <div className="min-h-screen bg-[#f8fafc] flex flex-col items-center justify-center p-4 md:p-6 font-['Cairo'] relative overflow-y-auto">
      <div className="w-full max-w-lg bg-white rounded-[3rem] md:rounded-[4rem] shadow-2xl border border-slate-50 overflow-hidden animate-in zoom-in duration-700 my-8">
        <div className="bg-[#2D9469] p-8 md:p-12 text-center relative">
          <div className="bg-white/10 p-4 rounded-[2rem] backdrop-blur-xl border border-white/20 inline-block mb-4 shadow-2xl">
             <img src={APP_LOGO_ICON} alt="Logo" className="h-12 w-12 md:h-16 md:w-16 mx-auto" />
          </div>
          <h1 className="text-3xl md:text-5xl font-black text-white tracking-tighter">وصـــلــهــا</h1>
          <p className="text-emerald-100/60 font-bold text-[9px] uppercase tracking-[0.4em] mt-2">المنوفية • الأمان والسرعة</p>
        </div>

        <div className="p-6 md:p-10">
          {errorMsg && <div className="mb-6 p-4 bg-rose-50 text-rose-600 rounded-2xl text-xs font-black border border-rose-100 animate-in shake duration-300">{errorMsg}</div>}

          <form onSubmit={handleAuth} className="space-y-4">
            {isRegistering ? (
              step === 'INPUT' ? (
                <div className="space-y-4 animate-in slide-in-from-bottom duration-500">
                  {/* User Role Selection */}
                  <div className="flex bg-slate-100 p-1.5 rounded-[1.5rem]">
                    <button type="button" onClick={() => setRole('CUSTOMER')} className={`flex-1 py-3 rounded-xl font-black text-[11px] transition-all ${role === 'CUSTOMER' ? 'bg-white text-[#2D9469] shadow-md' : 'text-slate-400'}`}>عميل</button>
                    <button type="button" onClick={() => setRole('DRIVER')} className={`flex-1 py-3 rounded-xl font-black text-[11px] transition-all ${role === 'DRIVER' ? 'bg-white text-[#2D9469] shadow-md' : 'text-slate-400'}`}>كابتن</button>
                  </div>

                  {/* Fields */}
                  <div className="relative group">
                    <UserIcon className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 h-5 w-5 group-focus-within:text-[#2D9469] transition-colors" />
                    <input type="text" placeholder="الاسم الرباعي" value={name} onChange={e => setName(e.target.value)} required className="w-full bg-slate-50 rounded-2xl py-4 md:py-5 pr-12 pl-6 font-bold outline-none text-sm border-2 border-transparent focus:border-emerald-500 transition-all" />
                  </div>

                  <div className="relative group">
                    <Smartphone className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 h-5 w-5 group-focus-within:text-[#2D9469] transition-colors" />
                    <input type="tel" placeholder="رقم الهاتف (010...)" value={phone} onChange={e => setPhone(e.target.value)} required className="w-full bg-slate-50 rounded-2xl py-4 md:py-5 pr-12 pl-6 font-bold outline-none text-sm text-left border-2 border-transparent focus:border-emerald-500 transition-all" dir="ltr" />
                  </div>

                  <div className="relative group">
                    <Mail className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 h-5 w-5 group-focus-within:text-[#2D9469] transition-colors" />
                    <input type="email" placeholder="البريد الإلكتروني" value={email} onChange={e => setEmail(e.target.value)} required className="w-full bg-slate-50 rounded-2xl py-4 md:py-5 pr-12 pl-6 font-bold outline-none text-sm text-left border-2 border-transparent focus:border-emerald-500 transition-all" dir="ltr" />
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="relative">
                      <Lock className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 h-5 w-5" />
                      <input type={showPassword ? "text" : "password"} placeholder="كلمة المرور" value={password} onChange={e => setPassword(e.target.value)} required className="w-full bg-slate-50 rounded-2xl py-4 md:py-5 pr-12 pl-12 font-bold outline-none text-sm text-left border-2 border-transparent focus:border-emerald-500 transition-all" dir="ltr" />
                      <button type="button" onClick={() => setShowPassword(!showPassword)} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 hover:text-slate-500">{showPassword ? <EyeOff className="h-5 w-5" /> : <Eye className="h-5 w-5" />}</button>
                    </div>
                    <div className="relative">
                      <Lock className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 h-5 w-5" />
                      <input type={showConfirmPassword ? "text" : "password"} placeholder="تأكيد كلمة المرور" value={confirmPassword} onChange={e => setConfirmPassword(e.target.value)} required className="w-full bg-slate-50 rounded-2xl py-4 md:py-5 pr-12 pl-12 font-bold outline-none text-sm text-left border-2 border-transparent focus:border-emerald-500 transition-all" dir="ltr" />
                      <button type="button" onClick={() => setShowConfirmPassword(!showConfirmPassword)} className="absolute left-4 top-1/2 -translate-y-1/2 text-slate-300 hover:text-slate-500">{showConfirmPassword ? <EyeOff className="h-5 w-5" /> : <Eye className="h-5 w-5" />}</button>
                    </div>
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
                    <div className="relative opacity-60">
                      <Globe className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-400 h-5 w-5" />
                      <input type="text" value="المنوفية" disabled className="w-full bg-slate-100 rounded-2xl py-4 md:py-5 pr-12 font-black text-sm border-2 border-slate-200 cursor-not-allowed" />
                    </div>
                    <div className="relative">
                      <Building className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 h-5 w-5" />
                      <select value={center} onChange={e => setCenter(e.target.value)} required className="w-full bg-slate-50 rounded-2xl py-4 md:py-5 pr-12 pl-6 font-bold outline-none text-sm appearance-none border-2 border-transparent focus:border-emerald-500 transition-all">
                        <option value="">اختر المركز</option>
                        {centers.map(c => <option key={c} value={c}>{c}</option>)}
                      </select>
                    </div>
                  </div>

                  <div className="relative group">
                    <MapPin className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 h-5 w-5 group-focus-within:text-[#2D9469] transition-colors" />
                    <input type="text" placeholder="اسم القرية / المنطقة" value={village} onChange={e => setVillage(e.target.value)} required className="w-full bg-slate-50 rounded-2xl py-4 md:py-5 pr-12 pl-6 font-bold outline-none text-sm border-2 border-transparent focus:border-emerald-500 transition-all" />
                  </div>

                  {role === 'DRIVER' && (
                    <div className="space-y-2 animate-in slide-in-from-top duration-300">
                       <label className="text-[10px] font-black text-slate-400 uppercase tracking-widest px-4">نوع المركبة المعتمد</label>
                       <div className="relative">
                        <Car className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 h-5 w-5" />
                        <select value={vehicleType} onChange={e => setVehicleType(e.target.value as VehicleType)} className="w-full bg-slate-50 rounded-2xl py-4 md:py-5 pr-12 pl-6 font-bold outline-none text-sm appearance-none border-2 border-transparent focus:border-emerald-500 transition-all">
                          <option value="TOKTOK">توك توك 🛺</option>
                          <option value="MOTORCYCLE">موتوسيكل 🏍️</option>
                          <option value="CAR">سيارة 🚗</option>
                        </select>
                       </div>
                    </div>
                  )}

                  <button type="submit" className="w-full bg-slate-900 text-white py-5 rounded-2xl font-black shadow-xl active:scale-95 transition-all flex items-center justify-center gap-3">متابعة التسجيل</button>
                </div>
              ) : (
                <div className="space-y-8 text-center animate-in zoom-in duration-500">
                  <div className="space-y-2">
                    <h2 className="text-2xl font-black">أثبت هويتك</h2>
                    <p className="text-xs font-bold text-slate-400">أدخل الكود المكون من 6 أرقام</p>
                  </div>

                  <div className="flex justify-center gap-2" dir="ltr">
                    {otp.map((digit, idx) => (
                      <input
                        key={idx}
                        // Fix: Use curly braces in ref callback to avoid returning the assignment result, which causes a TypeScript error in React refs.
                        ref={el => { otpRefs.current[idx] = el; }}
                        type="text"
                        maxLength={1}
                        value={digit}
                        onChange={e => handleOtpChange(idx, e.target.value)}
                        onKeyDown={e => handleOtpKeyDown(idx, e)}
                        className="w-10 h-14 md:w-12 md:h-16 bg-slate-50 border-2 border-slate-100 rounded-xl text-center text-2xl font-black focus:border-emerald-500 focus:ring-4 focus:ring-emerald-500/5 outline-none transition-all"
                      />
                    ))}
                  </div>

                  <div className="space-y-4">
                    <button type="button" onClick={sendWhatsAppCodeRequest} className="text-emerald-600 font-black text-xs hover:underline flex items-center justify-center gap-2 mx-auto">
                       <MessageCircle className="h-4 w-4" /> طلب الكود عبر الواتساب
                    </button>
                    <button type="submit" disabled={loading} className="w-full bg-[#2D9469] text-white py-5 rounded-2xl font-black shadow-xl active:scale-95 transition-all flex items-center justify-center gap-3">
                       {loading ? <Loader2 className="h-5 w-5 animate-spin" /> : 'إنشاء الحساب الآن'}
                    </button>
                    <button type="button" onClick={() => setStep('INPUT')} className="text-slate-400 font-bold text-[10px] uppercase tracking-widest">تعديل البيانات</button>
                  </div>
                </div>
              )
            ) : (
              <div className="space-y-5 animate-in slide-in-from-bottom duration-500">
                <div className="relative group">
