        <div className="flex items-center gap-3 md:gap-4 flex-row-reverse text-right">
          <span className={`text-base md:text-lg font-black ${selectedVillage ? 'text-slate-900' : 'text-slate-300'}`}>{selectedVillage?.name || "اختر الموقع"}</span>
          <div className={`${iconBg} p-3 md:p-4 rounded-xl md:rounded-2xl text-white shadow-xl`}>{icon}</div>
        </div>
      </div>

      {isOpen && (
        <div className="absolute top-full left-0 right-0 mt-2 bg-white rounded-[2rem] md:rounded-[3rem] shadow-2xl border border-slate-100 z-[200] max-h-[350px] md:max-h-[400px] overflow-hidden flex flex-col animate-in zoom-in">
          <div className="p-3 md:p-4 border-b border-slate-50 space-y-2">
             {selectedDistrict && (
               <button onClick={() => setSelectedDistrict(null)} className="flex items-center gap-2 text-emerald-600 font-black text-xs md:text-sm mb-2 hover:translate-x-1 transition-transform flex-row-reverse w-full text-right">
                  <ArrowLeft className="h-4 w-4" /> العودة لاختيار المركز
