               onChange={e => setSearchTerm(e.target.value)} 
               dir="rtl" 
               autoFocus
             />
          </div>

          <div className="flex-1 overflow-y-auto no-scrollbar p-3 md:p-4">
             {!selectedDistrict ? (
               <div className="space-y-1">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest text-right mb-2 px-2">اختر المركز أولاً</p>
