                    <button key={d.id} onClick={() => handleDistrictSelect(d)} className="w-full p-4 hover:bg-slate-50 rounded-2xl flex justify-between items-center transition-all flex-row-reverse group">
                       <div className="flex items-center gap-3 flex-row-reverse">
                          <div className="w-10 h-10 bg-emerald-50 text-emerald-600 rounded-xl flex items-center justify-center group-hover:bg-emerald-50 group-hover:text-white transition-colors"><Building className="h-5 w-5" /></div>
                          <span className="font-black text-slate-700 text-sm md:text-base">مركز {d.name}</span>
                       </div>
                       <ChevronRight className="h-4 w-4 text-slate-300 rotate-180 group-hover:text-emerald-500 group-hover:translate-x-[-4px] transition-all" />
                    </button>
                  ))}
               </div>
             ) : (
               <div className="space-y-1 animate-in slide-in-from-left">
                  <p className="text-[10px] font-black text-emerald-600 uppercase tracking-widest text-right mb-2 px-2 flex items-center justify-end gap-1">قرى مركز {selectedDistrict.name} <MapPin className="h-3 w-3" /></p>
                  {filteredVillages.map(v => (
                    <button key={v.id} onClick={() => handleVillageSelect(v)} className="w-full p-4 hover:bg-emerald-50 rounded-2xl flex justify-between items-center transition-all flex-row-reverse">
                       <span className="font-bold text-slate-700 text-sm md:text-base">{v.name}</span>
                       {selectedVillage?.id === v.id && <Check className="h-4 w-4 md:h-5 md:w-5 text-emerald-500" />}
                    </button>
