 */
const OrdersMonitor: React.FC<{ orders: Order[] }> = ({ orders }) => {
  const [searchTerm, setSearchTerm] = useState('');
  const [filter, setFilter] = useState<'ALL' | 'ACTIVE' | 'DONE' | 'CANCELLED' | 'WAITING'>('ALL');

  const filtered = orders.filter(o => {
    const matchesSearch = 
      o.customerPhone.includes(searchTerm) || 
      (o.driverName || '').includes(searchTerm) ||
      o.id.includes(searchTerm);

    if (filter === 'ACTIVE') return matchesSearch && [OrderStatus.ACCEPTED, OrderStatus.PICKED_UP, OrderStatus.ON_THE_WAY].includes(o.status);
    if (filter === 'DONE') return matchesSearch && [OrderStatus.DELIVERED, OrderStatus.DELIVERED_RATED].includes(o.status);
    if (filter === 'CANCELLED') return matchesSearch && o.status === OrderStatus.CANCELLED;
    if (filter === 'WAITING') return matchesSearch && o.status === OrderStatus.WAITING_FOR_OFFERS;
    return matchesSearch;
  });

  const getCategoryIcon = (cat: string) => {
    switch(cat) {
      case 'FOOD': return <UtensilsCrossed className="h-4 w-4" />;
      case 'PHARMACY': return <Pill className="h-4 w-4" />;
      default: return <Bike className="h-4 w-4" />;
