/**
 * إدارة المناطق والأسعار الذكية
 */
const MonofiaZonesManager: React.FC = () => {
  const [zones, setZones] = useState<Zone[]>([]);
  const [activeZoneId, setActiveZoneId] = useState<string | null>(null);
  const [newVillageName, setNewVillageName] = useState('');
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    return onSnapshot(collection(db, "zones"), (snap) => {
      setZones(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Zone[]);
    });
  }, []);

  const createZone = async (name: string) => {
    setLoading(true);
    try {
      const id = `zone_${Date.now()}`;
      await setDoc(doc(db, "zones", id), {
        id, name, villages: [], 
        pricing: { basePrice: 15, pricePerKm: 8, minPrice: 20, sameVillagePrice: 15, multipliers: { TOKTOK: 1.0, MOTORCYCLE: 0.8, CAR: 2.2 } }
      });
    } catch (e) { alert('خطأ'); } finally { setLoading(false); }
  };

  const updateZonePricing = async (zoneId: string, pricing: any) => {
    try {
      await updateDoc(doc(db, "zones", zoneId), { pricing });
      alert('تم تحديث التسعيرة للمنطقة');
    } catch (e) { alert('خطأ'); }
  };

  const addVillage = async (zoneId: string) => {
    if (!newVillageName.trim()) return;
    const zone = zones.find(z => z.id === zoneId);
    if (!zone) return;
    const villages = [...(zone.villages || []), { id: `v_${Date.now()}`, name: newVillageName, center: { lat: 30.5, lng: 31.0 } }];
    await updateDoc(doc(db, "zones", zoneId), { villages });
    setNewVillageName('');
  };

  return (
    <div className="space-y-10 animate-reveal text-right" dir="rtl">
       <div className="bg-white p-10 rounded-[4rem] border border-slate-100 shadow-xl flex flex-col md:flex-row justify-between items-center gap-8">
          <div><h3 className="text-3xl font-black text-slate-900 flex items-center gap-4"><Globe className="text-emerald-500" /> إدارة مراكز المنوفية</h3><p className="text-xs font-bold text-slate-400 mt-1 mr-14">التحكم في التغطية الجغرافية والتسعيرة الذكية</p></div>
          <button onClick={() => { const name = prompt('اسم المركز (مثلاً: أشمون، شبين):'); if(name) createZone(name); }} className="bg-slate-950 text-white px-10 py-5 rounded-[2rem] font-black text-xs flex items-center gap-3 active:scale-95 shadow-2xl transition-all"><PlusCircle className="h-5 w-5" /> إضافة مركز جديد</button>
       </div>

       <div className="grid grid-cols-1 lg:grid-cols-12 gap-8">
          <div className="lg:col-span-4 space-y-4">
             {zones.map(zone => (
               <div key={zone.id} onClick={() => setActiveZoneId(zone.id)} className={`p-8 rounded-[3rem] border-2 cursor-pointer transition-all flex items-center justify-between group ${activeZoneId === zone.id ? 'bg-slate-900 border-slate-900 text-white shadow-2xl scale-[1.02]' : 'bg-white border-slate-100 hover:border-emerald-500'}`}>
                  <div className="flex items-center gap-5">
                    <div className={`w-14 h-14 rounded-2xl flex items-center justify-center font-black text-xl ${activeZoneId === zone.id ? 'bg-emerald-500 text-white' : 'bg-slate-100 text-slate-400 group-hover:bg-emerald-50 group-hover:text-emerald-500'}`}>{zone.name[0]}</div>
                    <div><p className="font-black text-lg leading-none mb-1">مركز {zone.name}</p><p className={`text-[10px] font-bold ${activeZoneId === zone.id ? 'text-emerald-400' : 'text-slate-400'}`}>{zone.villages?.length || 0} قرية مضافة</p></div>
                  </div>
                  <ChevronRight className={`h-5 w-5 transition-transform ${activeZoneId === zone.id ? 'rotate-180 text-emerald-400' : 'text-slate-300'}`} />
               </div>
             ))}
          </div>

          <div className="lg:col-span-8">
             {activeZoneId ? (
               <div className="space-y-8 animate-in slide-in-from-left">
                  <div className="bg-white p-10 rounded-[4rem] shadow-xl border border-slate-100 space-y-10 relative overflow-hidden">
                     <div className="absolute top-0 left-0 w-64 h-64 bg-emerald-500/5 blur-[100px]"></div>
                     <h4 className="text-2xl font-black text-slate-900 flex items-center gap-3 relative z-10"><DollarSign className="text-emerald-500" /> تسعيرة مركز {zones.find(z => z.id === activeZoneId)?.name}</h4>
                     <div className="grid grid-cols-2 md:grid-cols-4 gap-6 relative z-10">
                        {[
                          { key: 'basePrice', label: 'فتح العداد' },
                          { key: 'pricePerKm', label: 'سعر الكيلومتر' },
                          { key: 'minPrice', label: 'أقل سعر رحلة' },
                          { key: 'sameVillagePrice', label: 'داخل القرية' }
                        ].map(item => (
                          <div key={item.key} className="bg-slate-50 p-6 rounded-[2.5rem] border border-slate-100 space-y-2">
                             <label className="text-[9px] font-black text-slate-400 uppercase">{item.label}</label>
                             <input type="number" 
                               value={zones.find(z => z.id === activeZoneId)?.pricing[item.key as keyof Zone['pricing']] as number} 
                               onChange={(e) => {
                                 const zone = zones.find(z => z.id === activeZoneId);
                                 if(zone) updateZonePricing(activeZoneId, { ...zone.pricing, [item.key]: Number(e.target.value) });
                               }} 
                               className="w-full bg-transparent font-black text-2xl outline-none text-slate-900" 
                             />
                          </div>
                        ))}
                     </div>
                  </div>

                  <div className="bg-white p-10 rounded-[4rem] shadow-xl border border-slate-100 space-y-8">
                     <div className="flex justify-between items-center px-4">
                        <h4 className="text-xl font-black flex items-center gap-3"><MapPin className="text-rose-500" /> القرى والعزب المعتمدة</h4>
                        <div className="flex gap-2">
                           <input value={newVillageName} onChange={e => setNewVillageName(e.target.value)} placeholder="اسم القرية..." className="bg-slate-50 rounded-2xl px-6 py-4 font-black text-xs outline-none text-right shadow-inner w-40 md:w-64" />
                           <button onClick={() => addVillage(activeZoneId)} className="bg-rose-600 text-white p-4 rounded-2xl active:scale-90 shadow-lg transition-all"><PlusCircle className="h-6 w-6" /></button>
                        </div>
                     </div>
                     <div className="grid grid-cols-1 md:grid-cols-2 gap-4 max-h-[400px] overflow-y-auto no-scrollbar p-2">
                        {zones.find(z => z.id === activeZoneId)?.villages?.map(v => (
                          <div key={v.id} className="p-5 bg-slate-50 rounded-[2rem] flex justify-between items-center hover:bg-white hover:shadow-lg transition-all group">
                             <span className="font-black text-slate-800">{v.name}</span>
                             <button onClick={async () => {
                               const zone = zones.find(z => z.id === activeZoneId);
                               if(zone) await updateDoc(doc(db, "zones", activeZoneId), { villages: zone.villages?.filter(vil => vil.id !== v.id) });
                             }} className="text-slate-300 hover:text-rose-500 opacity-0 group-hover:opacity-100 transition-all"><Trash2 className="h-5 w-5" /></button>
                          </div>
                        ))}
                     </div>
                  </div>
               </div>
             ) : (
               <div className="h-full flex flex-col items-center justify-center py-40 text-slate-300 bg-white rounded-[4rem] border-4 border-dashed border-slate-50">
                  <MapIcon className="h-20 w-20 mb-6 animate-pulse" />
                  <p className="font-black text-xl tracking-tight">اختر مركزاً من القائمة الجانبية لإدارة إعداداته</p>
               </div>
             )}
          </div>
       </div>
    </div>
  );
};

/**
 * طلبات المدفوعات - تم إصلاح الخطأ Index Error هنا
 */
const PaymentRequests: React.FC = () => {
  const [requests, setRequests] = useState<any[]>([]);
  const [loading, setLoading] = useState(false);

  useEffect(() => {
    // تم إزالة orderBy لتجنب خطأ الفهرس في Firestore، وإجراء الترتيب برمجياً
    const q = query(collection(db, "payment_requests"), where("status", "==", "PENDING"));
    return onSnapshot(q, (snap) => {
      const data = snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) }));
      // ترتيب برمي في جانب العميل
      setRequests(data.sort((a: any, b: any) => (b.createdAt || 0) - (a.createdAt || 0)));
    });
  }, []);

  const handleApprove = async (req: any) => {
    if (!confirm(`تأكيد صرف ${req.amount} ج.م للكابتن ${req.userName}؟`)) return;
    setLoading(true);
    try {
      const batch = writeBatch(db);
      batch.update(doc(db, "payment_requests", req.id), { status: 'APPROVED', approvedAt: Date.now() });
      const userRef = doc(db, "users", req.userId);
      const userSnap = await getDoc(userRef);
      if (userSnap.exists()) {
        const userData = userSnap.data();
        batch.update(userRef, { 
          "wallet.balance": (userData.wallet?.balance || 0) - req.amount,
          "wallet.withdrawn": (userData.wallet?.withdrawn || 0) + req.amount
        });
      }
      await addDoc(collection(db, "notifications"), {
        userId: req.userId, title: 'تم صرف أرباحك 💰', body: `تمت الموافقة على طلب سحب ${req.amount} ج.م.`, type: 'SUCCESS', createdAt: Date.now(), read: false
      });
      await batch.commit();
      alert('تمت العملية بنجاح');
    } catch (e) { alert('خطأ'); } finally { setLoading(false); }
  };

  return (
    <div className="bg-white p-12 rounded-[4rem] border border-slate-100 shadow-2xl space-y-10 animate-reveal text-right" dir="rtl">
       <div className="flex justify-between items-center px-4">
          <h3 className="text-2xl font-black text-slate-900 flex items-center gap-4"><Banknote className="text-emerald-500" /> طلبات صرف الأرباح</h3>
          <span className="bg-emerald-100 text-emerald-700 px-6 py-2 rounded-full font-black text-[10px] uppercase">{requests.length} طلب جديد</span>
       </div>
       <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {requests.map(req => (
            <div key={req.id} className="p-8 bg-slate-50 rounded-[3rem] border-2 border-transparent hover:border-emerald-500 hover:bg-white transition-all shadow-sm">
               <div className="flex justify-between items-start mb-6">
                  <div className="text-right">
                     <p className="font-black text-lg text-slate-900 leading-none mb-1">{req.userName}</p>
                     <p className="text-xs font-bold text-slate-400" dir="ltr">{req.userPhone}</p>
                  </div>
                  <div className="bg-slate-950 text-emerald-400 px-4 py-2 rounded-xl font-black text-lg">{req.amount}</div>
               </div>
               <div className="flex gap-2">
                  <button onClick={() => handleApprove(req)} disabled={loading} className="flex-1 bg-emerald-600 text-white py-4 rounded-2xl font-black text-xs shadow-lg active:scale-95 transition-all">
                    {loading ? <Loader2 className="animate-spin h-4 w-4 mx-auto" /> : 'موافقة وصرف'}
                  </button>
                  <button onClick={async () => { if(confirm('رفض الطلب؟')) await updateDoc(doc(db, "payment_requests", req.id), { status: 'REJECTED' }); }} className="bg-rose-50 text-rose-500 px-6 py-4 rounded-2xl font-black text-xs">رفض</button>
               </div>
            </div>
          ))}
          {requests.length === 0 && <div className="col-span-full py-20 text-center text-slate-300 font-black">لا توجد طلبات سحب حالياً</div>}
       </div>
    </div>
  );
};

