                   <div className="w-full grid grid-cols-2 gap-3 pt-6 border-t border-slate-200" dir="rtl"><div className="text-right"><p className="text-[8px] font-black text-slate-400 uppercase mb-1">الرصيد</p><p className="text-md font-black text-emerald-600">{(u.wallet?.balance || 0).toFixed(1)} <span className="text-[8px]">ج.م</span></p></div><div className="text-left"><p className="text-[8px] font-black text-slate-400 uppercase mb-1">الحالة</p><p className={`text-[10px] font-black uppercase ${u.status === 'APPROVED' ? 'text-emerald-500' : 'text-rose-500'}`}>{u.status}</p></div></div>
