  const [selectedDistrict, setSelectedDistrict] = useState<District | null>(null);

  const filteredDistricts = MENOFIA_DATA.filter(d => d.name.includes(searchTerm));
  const filteredVillages = selectedDistrict 
    ? selectedDistrict.villages.filter(v => v.name.includes(searchTerm)) 
    : [];

  const handleDistrictSelect = (d: District) => {
    setSelectedDistrict(d);
    setSearchTerm('');
