    <div className="relative space-y-1">
      <div className="flex flex-col px-2 text-right"><label className="label-strong">{label}</label><span className="helper-text">{helper}</span></div>
      <div onClick={() => setIsOpen(!isOpen)} className="bg-white border-2 border-slate-100 p-4 md:p-5 rounded-[1.8rem] md:rounded-[2.2rem] flex items-center justify-between cursor-pointer shadow-sm active:border-emerald-500 transition-all">
        <ChevronDown className={`h-4 w-4 md:h-5 md:w-5 text-slate-400 transition-transform ${isOpen ? 'rotate-180' : ''}`} />
        <div className="flex items-center gap-3 md:gap-4 flex-row-reverse text-right">
          <span className={`text-base md:text-lg font-black ${selectedVillage ? 'text-slate-900' : 'text-slate-300'}`}>{selectedVillage?.name || "اختر الموقع"}</span>
          <div className={`${iconBg} p-3 md:p-4 rounded-xl md:rounded-2xl text-white shadow-xl`}>{icon}</div>
        </div>
      </div>

      {isOpen && (
        <div className="absolute top-full left-0 right-0 mt-2 bg-white rounded-[2rem] md:rounded-[3rem] shadow-2xl border border-slate-100 z-[200] max-h-[350px] md:max-h-[400px] overflow-hidden flex flex-col animate-in zoom-in">
          <div className="p-3 md:p-4 border-b border-slate-50 space-y-2">
             {selectedDistrict && (
               <button onClick={() => setSelectedDistrict(null)} className="flex items-center gap-2 text-emerald-600 font-black text-xs md:text-sm mb-2 hover:translate-x-1 transition-transform flex-row-reverse w-full text-right">
                  <ArrowLeft className="h-4 w-4" /> العودة لاختيار المركز
               </button>
             )}
             <input 
               className="w-full bg-slate-50 border-none rounded-xl md:rounded-2xl py-3 md:py-4 px-5 md:px-6 text-xs md:text-sm font-black text-right outline-none" 
               placeholder={selectedDistrict ? `ابحث في قرى ${selectedDistrict.name}...` : "ابحث عن المركز (شبين، أشمون...)"} 
               value={searchTerm} 
               onChange={e => setSearchTerm(e.target.value)} 
               dir="rtl" 
               autoFocus
             />
          </div>

          <div className="flex-1 overflow-y-auto no-scrollbar p-3 md:p-4">
             {!selectedDistrict ? (
               <div className="space-y-1">
                  <p className="text-[10px] font-black text-slate-400 uppercase tracking-widest text-right mb-2 px-2">اختر المركز أولاً</p>
