                    <button key={d.id} onClick={() => handleDistrictSelect(d)} className="w-full p-4 hover:bg-slate-50 rounded-2xl flex justify-between items-center transition-all flex-row-reverse group">
                       <div className="flex items-center gap-3 flex-row-reverse">
