               <div className="space-y-1 animate-in slide-in-from-left">
                  <p className="text-[10px] font-black text-emerald-600 uppercase tracking-widest text-right mb-2 px-2 flex items-center justify-end gap-1">قرى مركز {selectedDistrict.name} <MapPin className="h-3 w-3" /></p>
