  const [loading, setLoading] = useState(false);

  const [restData, setRestData] = useState({ 
    name: '', 
    category: 'مشويات', 
    photoURL: '', 
    promoText: 'خصم خاص لمستخدمي وصلها'
  });

  useEffect(() => {
    return onSnapshot(collection(db, "restaurants"), (snap) => {
      setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]);
    });
  }, []);

  const toggleFeatured = async (rest: Restaurant) => {
    try {
      await updateDoc(doc(db, "restaurants", rest.id), { isFeatured: !rest.isFeatured });
    } catch (e) { alert('خطأ'); }
  };

  const saveRestaurant = async () => {
    if (!restData.name) return;
    setLoading(true);
    try {
      const id = `rest_${Date.now()}`;
      await setDoc(doc(db, "restaurants", id), {
        ...restData, id, menu: [], isOpen: true, address: 'أشمون', lat: 30.298, lng: 30.975, isFeatured: false
      });
      setIsAdding(false);
      setRestData({ name: '', category: 'مشويات', photoURL: '', promoText: '' });
    } catch (e) { alert('خطأ'); } finally { setLoading(false); }
  };

  return (
    <div className="space-y-8 animate-in slide-in-from-top">
      <div className="bg-white p-10 rounded-[4rem] border border-slate-100 shadow-xl">
        <div className="flex justify-between items-center mb-10 px-4">
           <button onClick={() => setIsAdding(!isAdding)} className="bg-emerald-600 text-white px-8 py-3 rounded-2xl font-black text-xs flex items-center gap-2 shadow-xl active:scale-95 transition-all">
