           <div>
              <h3 className="text-3xl font-black text-slate-900 flex items-center gap-3">إدارة المطاعم <UtensilsCrossed className="text-emerald-500" /></h3>
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">تحديد المطاعم المميزة للإعلانات</p>
