             <input value={restData.promoText} onChange={e => setRestData({...restData, promoText: e.target.value})} placeholder="نص الإعلان (مثلاً: خصم 20% اليوم)" className="w-full bg-white p-5 rounded-2xl font-black text-sm outline-none shadow-sm" dir="rtl" />
