          <button onClick={onClose} className="p-3 bg-white/10 rounded-2xl relative z-10 hover:bg-white/20 active:scale-90 transition-all"><ArrowRight className="h-6 w-6" /></button>
          <div className="text-right relative z-10">
             <h3 className="text-2xl font-black">{restaurant.name}</h3>
             <p className="text-xs font-bold text-emerald-400">{restaurant.category} • المنوفية</p>
          </div>
       </div>
       <div className="flex-1 overflow-y-auto p-6 space-y-6 no-scrollbar bg-slate-50">
          {restaurant.menuImageURL && (
            <button onClick={() => setShowFullMenu(true)} className="w-full bg-emerald-600 p-6 rounded-[2.5rem] text-white flex justify-between items-center shadow-xl border-none">
               <ZoomIn className="h-6 w-6" />
               <div className="text-right"><h4 className="font-black text-lg">تصفح المنيو</h4><p className="text-[10px]">عرض صورة المنيو كاملة</p></div>
            </button>
          )}
          <div className="space-y-4">
             {restaurant.menu?.map(item => (
               <div key={item.id} className="bg-white p-5 rounded-[2.5rem] shadow-sm border border-slate-100 flex justify-between items-center">
                  <div className="flex items-center gap-4">
                     <div className="flex items-center gap-2 bg-slate-50 p-2 rounded-2xl">
                        <button onClick={() => addToCart(item)} className="p-2 bg-emerald-500 text-white rounded-xl active:scale-75 transition-all"><Plus className="h-4 w-4" /></button>
                        <span className="font-black text-lg w-6 text-center">{cart.find(i => i.id === item.id)?.quantity || 0}</span>
                        <button onClick={() => removeFromCart(item.id)} className="p-2 bg-rose-50 text-rose-500 rounded-xl active:scale-75 transition-all"><Minus className="h-4 w-4" /></button>
                     </div>
                     <p className="font-black text-emerald-600">{item.price} ج.م</p>
                  </div>
                  <div className="text-right flex items-center gap-4 flex-row-reverse">
                     <div className="w-16 h-16 bg-slate-100 rounded-2xl overflow-hidden border border-slate-50 shrink-0">
