                     </div>
                     <div><p className="font-black text-slate-800 text-lg leading-tight">{item.name}</p></div>
                  </div>
               </div>
             ))}
          </div>
          <textarea value={notes} onChange={e => setNotes(e.target.value)} placeholder="ملاحظات إضافية على الطلب..." className="w-full bg-white border-2 border-slate-100 rounded-[2rem] p-5 text-sm font-bold outline-none text-right" dir="rtl" />
