const PaymentRequests: React.FC = () => {
  const [requests, setRequests] = useState<any[]>([]);
  useEffect(() => {
    return onSnapshot(query(collection(db, "payment_requests"), where("status", "==", "PENDING")), (snap) => {
      setRequests(snap.docs.map(d => ({ id: d.id, ...d.data() })));
    });
  }, []);

  const handleRequest = async (req: any, approve: boolean) => {
    const batch = writeBatch(db);
    batch.update(doc(db, "payment_requests", req.id), { status: approve ? 'APPROVED' : 'REJECTED' });
    if (approve) {
      const userRef = doc(db, "users", req.userId);
      const userSnap = await getDoc(userRef);
      if (userSnap.exists()) {
        const userData = userSnap.data();
        const currentBalance = userData.wallet?.balance || 0;
        const newBalance = req.type === 'TOPUP' ? currentBalance + req.amount : currentBalance - req.amount;
        batch.update(userRef, { 'wallet.balance': newBalance });

        const transId = `trans_${Date.now()}`;
        batch.set(doc(db, "transactions", transId), {
          id: transId,
          userId: req.userId,
          amount: req.amount,
          type: req.type === 'TOPUP' ? 'CREDIT' : 'DEBIT',
          description: req.type === 'TOPUP' ? 'شحن رصيد المحفظة' : 'سحب أرباح من المحفظة',
          createdAt: Date.now()
        });
      }
    }
    await batch.commit();
  };

  return (
    <div className="bg-white p-8 rounded-[3rem] shadow-xl space-y-6">
      <h3 className="text-xl font-black">طلبات الدفع</h3>
      <div className="space-y-4">
        {requests.map(r => (
          <div key={r.id} className="p-6 bg-slate-50 rounded-2xl flex justify-between items-center text-right">
            <div className="flex gap-2">
              <button onClick={() => handleRequest(r, false)} className="p-3 bg-rose-50 text-rose-500 rounded-xl">رفض</button>
              <button onClick={() => handleRequest(r, true)} className="p-3 bg-emerald-600 text-white rounded-xl">قبول</button>
            </div>
            <div>
              <p className="font-black">{r.amount} ج.م - {r.type === 'TOPUP' ? 'شحن' : 'سحب'}</p>
              <p className="text-sm font-bold text-slate-500">{r.userName} ({r.userPhone})</p>
            </div>
          </div>
        ))}
      </div>
    </div>
  );
};

