const UserFullEditor: React.FC<{ user: User, onClose: () => void }> = ({ user, onClose }) => {
  const [name, setName] = useState(user.name);
  const [phone, setPhone] = useState(user.phone);
  const [role, setRole] = useState(user.role);
  const [status, setStatus] = useState(user.status);
  const [loading, setLoading] = useState(false);

  const save = async () => {
    setLoading(true);
    try {
      await updateDoc(doc(db, "users", user.id), { name, phone, role, status });
      onClose();
    } catch (e) { alert('خطأ'); }
    finally { setLoading(false); }
  };

  return (
    <div className="fixed inset-0 z-[1000] bg-black/50 backdrop-blur-sm flex items-center justify-center p-4">
      <div className="bg-white w-full max-w-md rounded-[3rem] p-8 space-y-4 shadow-2xl">
        <h3 className="text-xl font-black">تعديل المستخدم</h3>
        <input value={name} onChange={e => setName(e.target.value)} className="w-full p-4 bg-slate-50 rounded-xl" placeholder="الاسم" />
        <input value={phone} onChange={e => setPhone(e.target.value)} className="w-full p-4 bg-slate-50 rounded-xl" placeholder="الهاتف" />
        <select value={role} onChange={e => setRole(e.target.value as any)} className="w-full p-4 bg-slate-50 rounded-xl">
          <option value="CUSTOMER">عميل</option>
          <option value="DRIVER">كابتن</option>
          <option value="OPERATOR">مشغل</option>
          <option value="ADMIN">مدير</option>
        </select>
        <select value={status} onChange={e => setStatus(e.target.value as any)} className="w-full p-4 bg-slate-50 rounded-xl">
          <option value="APPROVED">مفعل</option>
          <option value="PENDING_APPROVAL">انتظار</option>
          <option value="SUSPENDED">محظور</option>
        </select>
        <div className="flex gap-2">
          <button onClick={onClose} className="flex-1 py-4 font-bold">إلغاء</button>
          <button onClick={save} disabled={loading} className="flex-1 bg-slate-900 text-white py-4 rounded-xl font-bold">
            {loading ? 'جاري...' : 'حفظ التعديلات'}
          </button>
        </div>
      </div>
    </div>
  );
};

const RestaurantEditor: React.FC = () => {
  const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
