      const id = `rest_${Date.now()}`;
      await setDoc(doc(db, "restaurants", id), {
        ...restData, id, menu: [], isOpen: true, address: 'أشمون', lat: 30.298, lng: 30.975, isFeatured: false
      });
      setIsAdding(false);
      setRestData({ name: '', category: 'مشويات', photoURL: '', promoText: '' });
