              {isAdding ? <X className="h-4 w-4" /> : <PlusCircle className="h-4 w-4" />}
              {isAdding ? 'إلغاء' : 'إضافة مطعم جديد'}
           </button>
           <div className="text-right">
              <h3 className="text-3xl font-black text-slate-900 flex items-center gap-3 justify-end">إدارة الإعلانات <Megaphone className="text-emerald-500" /></h3>
              <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">تحديد المطاعم المميزة للظهور في واجهة العميل</p>
           </div>
        </div>

        {isAdding && (
          <div className="bg-slate-50 p-8 rounded-[3rem] mb-10 space-y-6 border-2 border-emerald-500/10">
             <input value={restData.name} onChange={e => setRestData({...restData, name: e.target.value})} placeholder="اسم المطعم" className="w-full bg-white p-5 rounded-2xl font-black text-sm outline-none shadow-sm" dir="rtl" />
             <input value={restData.promoText} onChange={e => setRestData({...restData, promoText: e.target.value})} placeholder="نص العرض (اختياري)" className="w-full bg-white p-5 rounded-2xl font-black text-sm outline-none shadow-sm" dir="rtl" />
             <button onClick={saveRestaurant} disabled={loading} className="w-full bg-slate-950 text-white py-6 rounded-3xl font-black shadow-2xl active:scale-95 transition-all">حفظ المطعم</button>
