const RestaurantMenu: React.FC<{ 
  restaurant: Restaurant, 
  onClose: () => void, 
  onCheckout: (cart: CartItem[], notes: string) => void 
}> = ({ restaurant, onClose, onCheckout }) => {
  const [cart, setCart] = useState<CartItem[]>([]);
  const [notes, setNotes] = useState('');
  const [showFullMenu, setShowFullMenu] = useState(false);

  const addToCart = (item: MenuItem) => {
    setCart(prev => {
      const existing = prev.find(i => i.id === item.id);
      if (existing) return prev.map(i => i.id === item.id ? { ...i, quantity: i.quantity + 1 } : i);
      return [...prev, { id: item.id, name: item.name, price: item.price, quantity: 1 }];
    });
  };

  const removeFromCart = (id: string) => {
    setCart(prev => prev.map(i => i.id === id ? { ...i, quantity: Math.max(0, i.quantity - 1) } : i).filter(i => i.quantity > 0));
  };

  const total = cart.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);

  return (
    <div className="fixed inset-0 bg-white z-[1100] flex flex-col animate-in slide-in-from-left duration-300">
       {showFullMenu && restaurant.menuImageURL && <FullMenuModal url={restaurant.menuImageURL} onClose={() => setShowFullMenu(false)} />}
       <div className="bg-slate-900 p-8 pt-14 text-white flex justify-between items-center shadow-xl relative overflow-hidden shrink-0">
          <button onClick={onClose} className="p-3 bg-white/10 rounded-2xl relative z-10 hover:bg-white/20 active:scale-90 transition-all"><ArrowRight className="h-6 w-6" /></button>
          <div className="text-right relative z-10">
             <h3 className="text-2xl font-black">{restaurant.name}</h3>
             <p className="text-xs font-bold text-emerald-400">{restaurant.category} • المنوفية</p>
          </div>
       </div>
       <div className="flex-1 overflow-y-auto p-6 space-y-6 no-scrollbar bg-slate-50">
          {restaurant.menuImageURL && (
            <button onClick={() => setShowFullMenu(true)} className="w-full bg-emerald-600 p-6 rounded-[2.5rem] text-white flex justify-between items-center shadow-xl border-none">
               <ZoomIn className="h-6 w-6" />
               <div className="text-right"><h4 className="font-black text-lg">تصفح المنيو</h4><p className="text-[10px]">عرض صورة المنيو كاملة</p></div>
            </button>
          )}
          <div className="space-y-4">
             {restaurant.menu?.map(item => (
               <div key={item.id} className="bg-white p-5 rounded-[2.5rem] shadow-sm border border-slate-100 flex justify-between items-center">
                  <div className="flex items-center gap-4">
                     <div className="flex items-center gap-2 bg-slate-50 p-2 rounded-2xl">
                        <button onClick={() => addToCart(item)} className="p-2 bg-emerald-500 text-white rounded-xl active:scale-75 transition-all"><Plus className="h-4 w-4" /></button>
                        <span className="font-black text-lg w-6 text-center">{cart.find(i => i.id === item.id)?.quantity || 0}</span>
                        <button onClick={() => removeFromCart(item.id)} className="p-2 bg-rose-50 text-rose-500 rounded-xl active:scale-75 transition-all"><Minus className="h-4 w-4" /></button>
                     </div>
                     <p className="font-black text-emerald-600">{item.price} ج.م</p>
                  </div>
                  <div className="text-right flex items-center gap-4 flex-row-reverse">
                     <div className="w-16 h-16 bg-slate-100 rounded-2xl overflow-hidden border border-slate-50 shrink-0">
                        {item.photoURL ? <img src={item.photoURL} className="w-full h-full object-cover" /> : <UtensilsCrossed className="p-4 text-slate-200" />}
                     </div>
                     <div><p className="font-black text-slate-800 text-lg leading-tight">{item.name}</p></div>
                  </div>
               </div>
             ))}
          </div>
          <textarea value={notes} onChange={e => setNotes(e.target.value)} placeholder="ملاحظات إضافية على الطلب..." className="w-full bg-white border-2 border-slate-100 rounded-[2rem] p-5 text-sm font-bold outline-none text-right" dir="rtl" />
       </div>
       {cart.length > 0 && (
         <div className="p-8 bg-white border-t border-slate-100 animate-in slide-in-from-bottom pb-12 shadow-2xl">
            <div className="flex justify-between items-center mb-6 px-2">
               <p className="text-2xl font-black text-slate-900">{total} ج.م</p>
               <p className="text-xs font-black text-slate-400">إجمالي الطلب</p>
            </div>
            <button onClick={() => onCheckout(cart, notes)} className="w-full bg-[#10b981] text-white py-7 rounded-[2.5rem] font-black text-lg shadow-2xl flex items-center justify-center gap-4 active:scale-95 transition-all">
               <ShoppingBag className="h-6 w-6" /> تأكيد طلب الطعام
            </button>
         </div>
       )}
    </div>
  );
};

