const Billboard: React.FC<{ items: Restaurant[], onSelect: (r: Restaurant) => void }> = ({ items, onSelect }) => {
  const scrollRef = useRef<HTMLDivElement>(null);
  const featuredItems = items.filter(r => r.isFeatured);

  useEffect(() => {
    if (featuredItems.length <= 1) return;
    const interval = setInterval(() => {
      if (scrollRef.current) {
        const { scrollLeft, offsetWidth, scrollWidth } = scrollRef.current;
        const maxScroll = scrollWidth - offsetWidth;
        if (scrollLeft >= maxScroll - 10) {
          scrollRef.current.scrollTo({ left: 0, behavior: 'smooth' });
        } else {
          scrollRef.current.scrollBy({ left: offsetWidth / 1.1, behavior: 'smooth' });
        }
      }
    }, 5000);
    return () => clearInterval(interval);
  }, [featuredItems]);

  if (featuredItems.length === 0) return null;

  return (
    <div ref={scrollRef} className="w-full overflow-x-auto no-scrollbar flex snap-x snap-mandatory gap-5 py-2 px-2">
      {featuredItems.map((rest) => (
        <div 
          key={rest.id} 
