          <div className={`${iconBg} p-4 rounded-2xl text-white shadow-xl`}>{icon}</div>
        </div>
      </div>
      {isOpen && (
        <div className="absolute top-full left-0 right-0 mt-2 bg-white rounded-[3rem] shadow-2xl border border-slate-100 z-[200] max-h-[350px] overflow-hidden flex flex-col animate-in zoom-in">
          <div className="p-4 border-b border-slate-50"><input className="w-full bg-slate-50 border-none rounded-2xl py-4 px-6 text-sm font-black outline-none text-right" placeholder="ابحث عن قريتك..." value={searchTerm} onChange={e => setSearchTerm(e.target.value)} dir="rtl" /></div>
          <div className="flex-1 overflow-y-auto no-scrollbar p-4">
             {filtered.map(v => (
               <button key={v.id} onClick={() => { onSelect(v); setIsOpen(false); }} className="w-full p-4 hover:bg-emerald-50 rounded-2xl flex justify-between items-center transition-all flex-row-reverse border border-transparent hover:border-emerald-100">
                  <span className="font-bold text-slate-700">{v.name}</span>
                  {selectedVillage?.id === v.id && <Check className="h-5 w-5 text-emerald-500" />}
               </button>
             ))}
          </div>
        </div>
      )}
    </div>
  );
};

// Billboard Component Updated to match the requested style (Vodafone/App Header Banner style)
const Billboard: React.FC<{ items: Restaurant[], onSelect: (r: Restaurant) => void }> = ({ items, onSelect }) => {
  const scrollRef = useRef<HTMLDivElement>(null);
  const [activeIndex, setActiveIndex] = useState(0);
  const featuredItems = items.filter(r => r.isFeatured);

  useEffect(() => {
    if (featuredItems.length <= 1) return;
    const interval = setInterval(() => {
      if (scrollRef.current) {
        const { scrollLeft, offsetWidth, scrollWidth } = scrollRef.current;
        const maxScroll = scrollWidth - offsetWidth;
        if (scrollLeft >= maxScroll - 10) {
          scrollRef.current.scrollTo({ left: 0, behavior: 'smooth' });
        } else {
          scrollRef.current.scrollBy({ left: offsetWidth, behavior: 'smooth' });
        }
      }
    }, 5000);
    return () => clearInterval(interval);
  }, [featuredItems]);

  const handleScroll = () => {
    if (scrollRef.current) {
      const index = Math.round(scrollRef.current.scrollLeft / scrollRef.current.offsetWidth);
      setActiveIndex(index);
    }
  };

  if (featuredItems.length === 0) return null;

  return (
    <div className="space-y-4 px-2">
      <div 
        ref={scrollRef} 
        onScroll={handleScroll}
        className="w-full overflow-x-auto no-scrollbar flex snap-x snap-mandatory rounded-[1.5rem] shadow-lg border border-slate-100"
      >
        {featuredItems.map((rest) => (
          <div 
            key={rest.id} 
            onClick={() => onSelect(rest)}
            className="relative min-w-full h-44 md:h-56 overflow-hidden snap-center cursor-pointer group transition-all"
          >
            {rest.photoURL ? (
              <img src={rest.photoURL} className="w-full h-full object-cover" alt={rest.name} />
            ) : (
              <div className="w-full h-full bg-slate-900 flex items-center justify-center">
                <UtensilsCrossed className="h-16 w-16 text-emerald-500/10" />
              </div>
            )}

            {/* Overlay for text legibility if needed, matching the clean red/dark look of the photo */}
            <div className="absolute inset-0 bg-gradient-to-l from-slate-950/60 via-transparent to-transparent p-6 flex flex-col justify-center items-end text-right">
                <h4 className="text-xl md:text-2xl font-black text-white drop-shadow-md">{rest.name}</h4>
                <p className="text-xs font-bold text-white/90 mt-1">{rest.promoText || 'عروض حصرية'}</p>
            </div>
          </div>
        ))}
      </div>

      {/* Dots Indicator - Matching the screenshot style */}
      <div className="flex justify-center gap-1.5 pt-1">
        {featuredItems.map((_, idx) => (
          <div 
            key={idx} 
            className={`h-2 rounded-full transition-all duration-300 ${activeIndex === idx ? 'w-4 bg-red-600' : 'w-2 bg-slate-200'}`}
          />
        ))}
      </div>
    </div>
  );
};

