                    <button key={cat.id} onClick={() => setSelectedCategory(cat.id as OrderCategory)} className={`py-6 md:py-8 rounded-[1.8rem] md:rounded-[2.5rem] flex flex-col items-center gap-2 border-4 transition-all ${selectedCategory === cat.id ? 'bg-white border-emerald-500 text-emerald-600 shadow-2xl scale-105' : 'bg-slate-50 border-transparent text-slate-400 opacity-60'}`}>
