const CustomerDashboard: React.FC<{ user: User }> = ({ user }) => {
  const [activeView, setActiveView] = useState<'NEW' | 'PROFILE' | 'ACTIVITY' | 'WALLET'>('NEW');
  const [selectedCategory, setSelectedCategory] = useState<OrderCategory>('TAXI');
  const [restaurants, setRestaurants] = useState<Restaurant[]>([]);
  const [viewingRestaurant, setViewingRestaurant] = useState<Restaurant | null>(null);
  const [showOffers, setShowOffers] = useState(false);

  // Ride states
  const [pickupVillage, setPickupVillage] = useState<Village | null>(null);
  const [dropoffVillage, setDropoffVillage] = useState<Village | null>(null);
  const [pickupNotes, setPickupNotes] = useState('');
  const [dropoffNotes, setDropoffNotes] = useState('');
  const [rideVehicleType, setRideVehicleType] = useState<VehicleType>('TOKTOK');

  const [activeOrder, setActiveOrder] = useState<Order | null>(null);
  const [aiOpen, setAiOpen] = useState(false);
  const [showChat, setShowChat] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [incomingOffers, setIncomingOffers] = useState<Offer[]>([]);

  const adminWhatsApp = "201065019364";

  const approxRidePrice = useMemo(() => {
    if (!pickupVillage || !dropoffVillage) return 0;
    const dist = calculateDistance(
      pickupVillage.center.lat, pickupVillage.center.lng,
      dropoffVillage.center.lat, dropoffVillage.center.lng
    );
    const multiplier = DEFAULT_PRICING.multipliers[rideVehicleType] || 1;
    if (pickupVillage.id === dropoffVillage.id) return DEFAULT_PRICING.sameVillagePrice;
    return Math.max(Math.round((DEFAULT_PRICING.basePrice + (dist * DEFAULT_PRICING.pricePerKm)) * multiplier), DEFAULT_PRICING.minPrice);
  }, [pickupVillage, dropoffVillage, rideVehicleType]);

  useEffect(() => {
    onSnapshot(collection(db, "restaurants"), (snap) => {
      setRestaurants(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Restaurant[]);
    });
    return onSnapshot(query(collection(db, "orders"), where("customerId", "==", user.id)), (snapshot) => {
      const all = snapshot.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) } as Order));
      setActiveOrder(all.find(o => ![OrderStatus.DELIVERED_RATED, OrderStatus.CANCELLED].includes(o.status)) || null);
    });
  }, [user.id]);

  useEffect(() => {
    if (activeOrder?.status === OrderStatus.WAITING_FOR_OFFERS) {
      return onSnapshot(query(collection(db, "offers"), where("orderId", "==", activeOrder.id)), (snap) => {
        setIncomingOffers(snap.docs.map(d => ({ id: d.id, ...stripFirestore(d.data()) })) as Offer[]);
      });
    }
  }, [activeOrder]);

  const handleCreateRideOrder = async () => {
    if(!pickupVillage || !dropoffVillage) return alert('يرجى اختيار النقطتين');
    setIsSubmitting(true);
    try {
       const dist = calculateDistance(pickupVillage.center.lat, pickupVillage.center.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
       await addDoc(collection(db, "orders"), {
          customerId: user.id, customerPhone: user.phone, category: 'TAXI',
          pickup: { address: pickupVillage.name, lat: pickupVillage.center.lat, lng: pickupVillage.center.lng, villageName: pickupVillage.name },
          dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name },
          pickupNotes: pickupNotes.trim(), dropoffNotes: dropoffNotes.trim(),
          status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), 
          requestedVehicleType: rideVehicleType, price: approxRidePrice, distance: dist,
          operatorId: 'op_main', zoneId: 'zone_main', paymentMethod: 'CASH'
       });
       const waMsg = `📢 *طلب مشوار جديد من تطبيق وصلها*\n👤 *العميل:* ${user.name}\n📍 *من:* ${pickupVillage.name}\n🏁 *إلى:* ${dropoffVillage.name}\n💰 *السعر المتوقع:* ${approxRidePrice} ج.م`;
       window.open(`https://wa.me/${adminWhatsApp}?text=${encodeURIComponent(waMsg)}`, '_blank');
    } catch(e) { alert('خطأ'); } finally { setIsSubmitting(false); }
  };

  const handleCheckoutFood = async (cart: CartItem[], notes: string) => {
    if (!viewingRestaurant || !dropoffVillage) return alert('يرجى اختيار مكان التوصيل');
    setIsSubmitting(true);
    try {
      const dist = calculateDistance(viewingRestaurant.lat, viewingRestaurant.lng, dropoffVillage.center.lat, dropoffVillage.center.lng);
      const deliveryPrice = Math.max(Math.round(DEFAULT_PRICING.basePrice + (dist * DEFAULT_PRICING.pricePerKm)), DEFAULT_PRICING.minPrice);
      const foodTotal = cart.reduce((acc, curr) => acc + (curr.price * curr.quantity), 0);
      await addDoc(collection(db, "orders"), {
        customerId: user.id, customerPhone: user.phone, category: 'FOOD',
        pickup: { address: viewingRestaurant.name, lat: viewingRestaurant.lat, lng: viewingRestaurant.lng, villageName: viewingRestaurant.address },
        dropoff: { address: dropoffVillage.name, lat: dropoffVillage.center.lat, lng: dropoffVillage.center.lng, villageName: dropoffVillage.name },
        status: OrderStatus.WAITING_FOR_OFFERS, createdAt: Date.now(), requestedVehicleType: 'MOTORCYCLE',
        price: deliveryPrice + foodTotal, distance: dist, operatorId: 'op_main', zoneId: 'zone_main',
        paymentMethod: 'CASH', foodItems: cart, restaurantId: viewingRestaurant.id, restaurantName: viewingRestaurant.name,
        notes: notes.trim()
      });
      setViewingRestaurant(null);
    } catch(e) { alert('خطأ'); } finally { setIsSubmitting(false); }
  };

  const handleAcceptOffer = async (offer: Offer) => {
    if (!activeOrder) return;
    try {
      await updateDoc(doc(db, "orders", activeOrder.id), {
        driverId: offer.driverId, driverName: offer.driverName, driverPhone: offer.driverPhone,
        driverPhoto: offer.driverPhoto || null, status: OrderStatus.ACCEPTED, acceptedAt: Date.now()
      });
    } catch (e) { alert('فشل قبول العرض'); }
  };

  if (showChat && activeOrder) return <ChatView user={user} order={activeOrder} onBack={() => setShowChat(false)} />;
  if (activeView === 'WALLET') return <WalletView user={user} onBack={() => setActiveView('NEW')} />;
  if (activeView === 'PROFILE') return <ProfileView user={user} onUpdate={() => {}} onBack={() => setActiveView('NEW')} onOpenWallet={() => setActiveView('WALLET')} />;
  if (activeView === 'ACTIVITY') return <ActivityView user={user} onBack={() => setActiveView('NEW')} />;

  return (
    <div className="rh-layout h-full relative overflow-hidden bg-white">
      <AIAssistant isOpen={aiOpen} onClose={() => setAiOpen(false)} />
      {viewingRestaurant && <RestaurantMenu restaurant={viewingRestaurant} onClose={() => setViewingRestaurant(null)} onCheckout={handleCheckoutFood} />}
      {showOffers && <OffersSheet items={restaurants} onClose={() => setShowOffers(false)} onSelect={setViewingRestaurant} />}

      {/* Floating Offer Button */}
      {selectedCategory === 'FOOD' && !activeOrder && (
        <button 
          onClick={() => setShowOffers(true)}
          className="fixed bottom-24 right-6 z-[120] bg-rose-600 text-white p-5 rounded-full shadow-[0_15px_40px_rgba(225,29,72,0.4)] border-4 border-white active:scale-90 transition-all group overflow-hidden"
        >
          <Percent className="h-7 w-7 relative z-10 group-hover:rotate-12" />
          <div className="absolute inset-0 bg-white opacity-0 group-hover:opacity-20 transition-opacity"></div>
        </button>
      )}

      <div className="rh-ui-panel no-scrollbar z-[100] translate-y-0 bg-white shadow-none">
        <div className="bottom-sheet-grabber lg:hidden"></div>
        <div className="p-4 md:p-8 space-y-6 md:space-y-8 pb-32 max-w-2xl mx-auto h-full overflow-y-auto no-scrollbar text-right">
          {!activeOrder ? (
            <>
              {/* Header - Resigned to match screenshot layout */}
              <div className="flex items-center justify-between px-2 pt-2">
                 <button onClick={() => setAiOpen(true)} className="p-3 bg-slate-100/80 rounded-full text-slate-500 active:scale-90 shadow-sm">
                   <Search className="h-5 w-5" />
                 </button>

                 <div className="w-12 h-12 bg-white rounded-full flex items-center justify-center border-4 border-slate-50 shadow-md p-1 overflow-hidden">
                   <img src="https://img.icons8.com/fluency/512/vodafone.png" className="w-full h-full object-contain" alt="Logo" />
                 </div>
              </div>

              {/* Billboard: Matches Screenshot Flow */}
              <div className="animate-in fade-in duration-700">
                <Billboard items={restaurants} onSelect={setViewingRestaurant} />
              </div>

              {/* Service Categories */}
              <div className="grid grid-cols-3 gap-3 md:gap-4 px-2">
                  {[
                    { id: 'TAXI', label: 'مشوار', icon: <Bike className="h-6 w-6" /> },
                    { id: 'FOOD', label: 'أكل', icon: <UtensilsCrossed className="h-6 w-6" /> },
                    { id: 'PHARMACY', label: 'صيدلية', icon: <Pill className="h-6 w-6" /> }
                  ].map(cat => (
                    <button key={cat.id} onClick={() => setSelectedCategory(cat.id as OrderCategory)} className={`py-6 md:py-8 rounded-[1.8rem] md:rounded-[2.5rem] flex flex-col items-center gap-2 border-4 transition-all ${selectedCategory === cat.id ? 'bg-white border-emerald-500 text-emerald-600 shadow-2xl scale-105' : 'bg-slate-50 border-transparent text-slate-400 opacity-60'}`}>
                       {cat.icon} <span className="text-[9px] md:text-[11px] font-black uppercase tracking-widest">{cat.label}</span>
                    </button>
                  ))}
              </div>

              {/* Conditional View Content */}
              {selectedCategory === 'FOOD' ? (
                <div className="space-y-6 md:space-y-8 animate-in zoom-in duration-500">
                   <VillageInput label="التوصيل إلى" helper="أين ستستلم طلبك؟" icon={<MapPin className="h-5 w-5" />} iconBg="bg-rose-500" selectedVillage={dropoffVillage} onSelect={setDropoffVillage} />

                   <div className="grid grid-cols-1 gap-4 md:gap-6">
                      <div className="flex items-center justify-between px-2 pt-4 border-t border-slate-100">
                         <h5 className="text-[10px] font-black text-slate-400 uppercase tracking-[0.2em]">كل المطاعم المتاحة</h5>
                         <Building2 className="h-4 w-4 text-slate-200" />
                      </div>
                      {restaurants.map(rest => (
                        <div key={rest.id} onClick={() => setViewingRestaurant(rest)} className="bg-white p-5 rounded-[2.2rem] border border-slate-100 shadow-sm flex flex-row-reverse justify-between items-center hover:border-emerald-500 transition-all cursor-pointer group active:scale-[0.98]">
                           <div className="flex items-center gap-4 flex-row-reverse text-right">
                              <div className="w-14 h-14 bg-slate-900 rounded-[1.2rem] flex items-center justify-center overflow-hidden shadow-lg">
                                 {rest.photoURL ? <img src={rest.photoURL} className="w-full h-full object-cover" /> : <UtensilsCrossed className="h-6 w-6 text-emerald-400" />}
                              </div>
                              <div><h4 className="text-lg font-black text-slate-800 leading-tight">{rest.name}</h4><p className="text-[9px] font-bold text-slate-400 mt-0.5">{rest.category}</p></div>
                           </div>
                           <div className="flex items-center gap-2">
                             {rest.isFeatured && <Star className="h-4 w-4 text-amber-500 fill-amber-500" />}
                             <ChevronRight className="h-5 w-5 text-slate-200 rotate-180 group-hover:text-emerald-500 transition-colors" />
                           </div>
                        </div>
                      ))}
                   </div>
                </div>
              ) : (
                <div className="space-y-6 md:space-y-10 animate-in slide-in-from-right duration-500">
                   <div className="space-y-6">
                      <VillageInput label="أنا موجود في" helper="نقطة استلامك" icon={<MapPin className="h-5 w-5" />} iconBg="bg-emerald-500" selectedVillage={pickupVillage} onSelect={setPickupVillage} />
                      <input value={pickupNotes} onChange={e => setPickupNotes(e.target.value)} placeholder="وصف مكان الاستلام (مثلاً: بجوار صيدلية كذا)" className="w-full bg-slate-50 rounded-[1.5rem] p-5 text-sm font-bold outline-none text-right focus:border-emerald-500 transition-all shadow-inner" dir="rtl" />
                      <VillageInput label="أريد الذهاب إلى" helper="وجهتك النهائية" icon={<Check className="h-5 w-5" />} iconBg="bg-rose-500" selectedVillage={dropoffVillage} onSelect={setDropoffVillage} />
                      <input value={dropoffNotes} onChange={e => setDropoffNotes(e.target.value)} placeholder="وصف الوجهة (مثلاً: خلف بنك مصر)" className="w-full bg-slate-50 rounded-[1.5rem] p-5 text-sm font-bold outline-none text-right focus:border-emerald-500 transition-all shadow-inner" dir="rtl" />
                   </div>
                   <div className="grid grid-cols-3 gap-3">
                      {[
                        {id: 'TOKTOK', label: 'توكتوك', icon: <Zap className="h-5 w-5" />},
                        {id: 'MOTORCYCLE', label: 'موتوسيكل', icon: <Bike className="h-5 w-5" />},
                        {id: 'CAR', label: 'سيارة', icon: <Car className="h-5 w-5" />}
                      ].map(v => (
                        <button key={v.id} onClick={() => setRideVehicleType(v.id as VehicleType)} className={`py-5 rounded-[1.8rem] flex flex-col items-center gap-2 transition-all border-2 ${rideVehicleType === v.id ? 'bg-emerald-50 border-emerald-500 text-emerald-600 shadow-lg scale-105' : 'bg-white border-slate-50 text-slate-300'}`}>
                           {v.icon}<span className="text-[10px] font-black uppercase tracking-widest">{v.label}</span>
                        </button>
                      ))}
                   </div>
                   {approxRidePrice > 0 && (
                     <div className="bg-emerald-900 text-white p-8 rounded-[3rem] shadow-2xl flex justify-between items-center animate-reveal relative overflow-hidden group">
                        <p className="text-4xl font-black">{approxRidePrice} <span className="text-xs opacity-40 uppercase">ج.م</span></p>
                        <div className="text-right"><p className="text-[9px] font-black text-emerald-400 uppercase tracking-[0.3em] mb-1">السعر التقريبي</p><p className="text-xs font-bold opacity-60">مشوار مريح وآمن</p></div>
                     </div>
                   )}
                   <button onClick={handleCreateRideOrder} disabled={!pickupVillage || !dropoffVillage || isSubmitting} className="w-full bg-slate-950 text-white py-7 rounded-[2.5rem] font-black text-2xl shadow-2xl active:scale-95 transition-all flex items-center justify-center gap-4">
                      {isSubmitting ? <Loader2 className="animate-spin h-8 w-8" /> : 'اطلب الآن'}
                   </button>
                </div>
              )}
            </>
          ) : (
            <div className="space-y-12">
               {activeOrder.status === OrderStatus.WAITING_FOR_OFFERS ? (
                 <div className="animate-in zoom-in duration-700 space-y-12 text-center">
                    <Navigation2 className="h-24 w-24 text-emerald-600 animate-bounce mx-auto" />
                    <h2 className="text-3xl font-black text-slate-950 tracking-tighter">جاري جلب كباتن متاحين...</h2>
                    <div className="space-y-5">
                       {incomingOffers.map(offer => (
                         <div key={offer.id} className="bg-white p-8 rounded-[3.5rem] border-4 border-slate-50 shadow-2xl flex justify-between items-center hover:border-emerald-500 transition-all">
                            <div className="text-center space-y-2">
                               <p className="text-3xl font-black text-emerald-700">{offer.price} ج.م</p>
                               <button onClick={() => handleAcceptOffer(offer)} className="bg-emerald-600 text-white px-10 py-2.5 rounded-2xl font-black text-[10px] shadow-lg">قبول الرحلة</button>
                            </div>
                            <div className="flex items-center gap-5 flex-row-reverse text-right">
                               <div className="w-16 h-16 bg-slate-950 text-emerald-400 rounded-2xl flex items-center justify-center font-black text-2xl shadow-xl">{(offer.driverName || 'ك')[0]}</div>
                               <div><p className="font-black text-slate-900 text-lg">{offer.driverName}</p><div className="flex items-center gap-2 text-amber-500 font-black text-[10px] bg-amber-50 px-4 py-1 rounded-full mt-1">{offer.driverRating} <Star className="h-3 w-3 fill-amber-400" /></div></div>
                            </div>
                         </div>
                       ))}
                    </div>
                    <button onClick={() => updateDoc(doc(db, "orders", activeOrder.id), { status: OrderStatus.CANCELLED })} className="text-rose-500 font-black text-[10px] uppercase tracking-[0.3em] hover:underline transition-all">إلغاء الطلب</button>
                 </div>
               ) : (
                 <div className="animate-in zoom-in duration-700 space-y-10 text-center">
                    <div className="bg-emerald-600 p-8 rounded-[3.5rem] text-white flex justify-between items-center shadow-2xl relative overflow-hidden">
                       <div className="text-right relative z-10"><h3 className="text-2xl font-black">الكابتن في طريقه إليك</h3></div>
                       <Navigation2 className="h-8 w-8 animate-bounce relative z-10" />
                    </div>
                    <div className="w-32 h-32 bg-white rounded-[3.5rem] mx-auto flex items-center justify-center border-8 border-slate-50 shadow-2xl font-black text-5xl text-slate-200">{(activeOrder.driverName || 'ك')[0]}</div>
                    <h4 className="text-3xl font-black text-slate-900">{activeOrder.driverName}</h4>
                    <div className="grid grid-cols-2 gap-4">
                       <a href={`tel:${activeOrder.driverPhone}`} className="bg-slate-950 text-white py-7 rounded-[2.5rem] font-black text-lg flex items-center justify-center gap-4 shadow-2xl active:scale-95 transition-all"><PhoneCall className="h-7 w-7" /> اتصال</a>
                       <button onClick={() => setShowChat(true)} className="bg-white border-4 border-slate-100 text-slate-900 py-7 rounded-[2.5rem] font-black text-lg flex items-center justify-center gap-4 relative active:scale-95 transition-all"><MessageCircle className="h-7 w-7" /> محادثة</button>
                    </div>
                 </div>
               )}
            </div>
          )}
        </div>
      </div>

      <nav className="fixed bottom-0 left-0 right-0 bg-white/95 backdrop-blur-2xl border-t border-slate-100 px-8 py-6 flex justify-around items-center z-[150] shadow-2xl flex-row-reverse">
         {[
           {id: 'NEW', icon: <Plus className="h-7 w-7" />, label: 'طلب'},
           {id: 'ACTIVITY', icon: <History className="h-7 w-7" />, label: 'نشاطي'},
           {id: 'PROFILE', icon: <UserIcon className="h-7 w-7" />, label: 'حسابي'}
         ].map(tab => (
           <button key={tab.id} onClick={() => setActiveView(tab.id as any)} className={`flex flex-col items-center gap-2 transition-all ${activeView === tab.id ? 'text-emerald-600 scale-110' : 'text-slate-300'}`}>
              <div className={`p-3 rounded-2xl ${activeView === tab.id ? 'bg-emerald-50 shadow-inner' : ''}`}>{tab.icon}</div>
              <span className="text-[9px] font-black uppercase tracking-widest">{tab.label}</span>
           </button>
         ))}
      </nav>
    </div>
  );
};

export default CustomerDashboard;
